import type { EngineInterface, Register } from 'claude-code'

import type { FlowDefaults, FlowTask, JevMode } from '../types'
import {
  allowPhase,
  approvePhase,
  GATED,
  PLANNING,
  createdUrls,
  editGate,
  gateArtifact,
  inside,
  isFlow,
  isHelpers,
  isStage,
  isTracked,
  skillName,
  stageStart,
  stagesOf,
  stageInput,
  mcpCreatedUrls,
  nextAction,
  parseNew,
  recordEvent,
  scratchPointer,
  statusOf,
} from './flow'
import { ASK_JEV_TOOL } from './ask'
import { STAGE_DONE, STAGE_DONE_TOOL, registerAutonomy } from './autonomy'
import { registerDialog } from './dialog'
import { registerDoc } from './doc'
import { registerRecap } from './recap'
import { explain } from './debug'
import { FLOWS, FLOW_NAMES, STATUS_LABEL, UPSTREAM } from './flows'
import { JEV_MODEL, JEV_URL, LOG_KEY, logSummary, parseLog } from './jev'
import { observe, registerJudge } from './judge'
import { landed } from './landed'
import { ponytailNote } from './ponytail'
import { registerNoun } from './noun'
import { registerQuickbar } from './quickbar'
import { configRowOf } from './prefs'
import { SETTINGS_OPEN, registerSettings } from './settings'
import { BUILD, isCode, isUndone, leaveHold, maskedNote, proofGap, seenIn, shipHold } from './proof'
import { SETUP_FILE, checksIn, reminder, trackerOf, unsettledPr, withoutBodies } from './trail'
import { segmentsFor, stripLine } from './strip'
import { RAIL_OPEN, actionLabel, holdNote, runsOn } from './status'
import { commandLine, registerUi } from './ui'

const USAGE = [
  `Usage: /flow new [--workflow ${FLOW_NAMES.join('|')}] [--start ticket|idea|broken|foggy] [--model <model>] [--effort <effort>] [--plan-model <model>] [--plan-effort <effort>] [--helpers own|stage|fable|opus|sonnet|haiku] [--critic] [--rules <path>] [--no-pr|--push] [--worktree] [--ui] <what are we doing>`,
  "/flow and /flow board open the board: every task, the open one's stages and what to do next. /flow switch <slug>, /flow use <workflow> changes the workflow",
  '/flow new with no text opens the new-task dialog; /flow doc [pointer] opens the artifact tab; /flow bar edits the quickbar',
  '/flow approve [path or link], /flow allow [why] (lifts a planning edit hold, or waives the proof a build needs), /flow skip [why] (moves past a stage), /flow done (closes the task, at any point)',
  '/flow why says what the task\'s state is made of and why it holds; /flow followup turns a retro\'s findings into the next task',
  '/flow recap [new] catches you up on the side, in its own pane; /flow settings opens every setting',
  '/flow share <board artifact link> sends every task to a claude.ai board; /flow share off stops',
  '/flow jev shows what Jev judged lately; /flow jev off|shadow|on sets it',
].join('\n')

const JEV_MODES: readonly JevMode[] = ['off', 'shadow', 'on']
const isJevMode = (word: string): word is JevMode => (JEV_MODES as readonly string[]).includes(word)

// The validator lists state reads per file, so each file spells its reference.
const settingsNote = { plugin: 'flow', key: 'settings' } as const

const busyRef = { plugin: 'flow', key: 'busy' } as const

const BOARD_LINK = /^https:\/\/claude\.ai\/(code\/)?artifact\/[\w-]+$/

/** Origins a person stands behind: typed, or sent from their phone; the flow mod's own buttons are pressed by one. `sdk` is a host's own turn. */
const PERSON = ['composer', 'bridge']

/** What to do next, in words: the next stage, or first the proof or the call a held task waits on. */
const nextLine = (task: FlowTask) => {
  const status = statusOf(task, false)
  const hold = holdNote(task, status)

  return hold === undefined
    ? `Next: ${commandLine(task)} (${nextAction(task).why})`
    : `Next: ${status === 'stuck' ? 'your call' : 'prove it'} (${hold}), then ${actionLabel(task)} (${commandLine(task)})`
}

/** The task in a few lines: what the person reads in the transcript and the model reads as context. */
const describe = (task: FlowTask) => {
  const status = statusOf(task, false)

  return [
    `${task.title} (${FLOWS[task.flow].label}, ${STATUS_LABEL[status].toLowerCase()}) .scratch/${task.slug}/task.json`,
    ...(task.flow === 'freeform' ? [] : [stripLine(segmentsFor(task, status))]),
    ...(runsOn(task) === undefined ? [] : [`Runs on: ${runsOn(task)}`]),
    ...(task.helpers === undefined ? [] : [`Helper agents: ${task.helpers}`]),
    ...(task.artifacts.length === 0 ? [] : [`Artifacts: ${task.artifacts.map(one => one.pointer).join(', ')}`]),
    nextLine(task),
  ].join('\n')
}

/** Records each link as the phase's artifact, in order; a pull request's CI is watched until it settles. */
/**
 * Records a build's unproven edits as undone once the tree is back where it was: nothing to prove,
 * so the gate stops asking. Only asks git while there is a gap.
 */
// ponytail: whole-tree status, so an unrelated change elsewhere keeps the gate up; a per-path diff if that bites.
const noteUndone = async ($: EngineInterface) => {
  const open = await $.flow.task()
  if (open === null || !BUILD.includes(open.phase) || proofGap(open) === undefined) {
    return
  }
  const cwd = await $.session.root()
  const git = (args: string[]) => $.process.run(['git', ...args], { cwd }).then(ran => ran.stdout, () => undefined)
  const status = await git(['status', '--porcelain'])
  const head = status?.trim() === '' ? await git(['log', '-1', '--format=%ct']) : undefined
  if (status !== undefined && head !== undefined && isUndone(open, status, head)) {
    await $.flow.note({ kind: 'reverted' })
  }
}

const recordLinks = async (
  $: { flow: { produce: (input: { pointer: string }) => Promise<unknown>; watch: (input: { url: string }) => Promise<unknown> } },
  urls: readonly string[],
) => {
  for (const url of urls) {
    await $.flow.produce({ pointer: url })
    if (url.includes('/pull/')) {
      await $.flow.watch({ url })
    }
  }
}

export const register: Register = (on, options) => {
  const isAutoAdvance = options.autoAdvance === true
  const clearAt = typeof options.clearAt === 'number' ? options.clearAt : 50

  const text = (value: unknown, fallback: string) => (typeof value === 'string' && value.trim() !== '' ? value.trim() : fallback)
  // What else counts as a check here, beside the runners trail.ts knows: `scripts/ci.sh, make smoke`.
  const checks = text(options.checks, '')
    .split(',')
    .map(one => one.trim())
    .filter(one => one !== '')
  const jevMode: JevMode = options.jevMode === 'shadow' || options.jevMode === 'on' ? options.jevMode : 'off'

  registerNoun(on, { mode: jevMode, apiKey: text(options.jevApiKey, ''), baseUrl: text(options.jevBaseUrl, JEV_URL), model: text(options.jevModel, JEV_MODEL) })
  registerJudge(on, jevMode)
  // What a new task runs on unless the person picks otherwise.
  // `session` in a model picker keeps the session's model.
  const [model, planModel, rules] = [options.buildModel, options.planModel, options.rules].map(one => text(one, '')).map(one => (one === 'session' ? '' : one))
  const defaults: FlowDefaults = {
    ...(model === '' ? {} : { model }),
    ...(planModel === '' ? {} : { planModel }),
    ...(isHelpers(options.helpers) ? { helpers: options.helpers } : {}),
    ...(options.critic === true ? { critic: true } : {}),
    ...(rules === '' ? {} : { rules }),
  }
  registerUi(on, clearAt, jevMode, defaults)
  registerDialog(on, defaults, jevMode)
  registerDoc(on)
  registerRecap(on)
  registerQuickbar(on)
  registerSettings(on, options)
  const criticPanel = ['fable', 'opus', 'sonnet', 'haiku'].includes(text(options.criticPanel, '')) ? text(options.criticPanel, '') : 'off'
  registerAutonomy(on, { isAutoAdvance, clearAt, criticPanel })

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'flow',
      description: 'Track a task through the idea-to-ship flow',
      argumentHint: '[new [<what are we doing>] | board | switch <slug> | use <workflow> | doc [pointer] | bar | share <link> | jev [off|shadow|on] | settings | recap [new] | why | skip | followup | approve | allow | done]',
    })
    await $.tool.register(STAGE_DONE_TOOL)
    await $.tool.register(ASK_JEV_TOOL)
    const pr = unsettledPr(await $.flow.resume())
    if (pr !== undefined) {
      await $.flow.watch({ url: pr })
    }
    // The board stays shut until asked for: with no task open, the line under the prompt is the way in.
    await $.flow.suggest()
    // A change to an option reloads the mod and forgets the settings pane was open: the state remembers, and this load opens it again.
    const settings = (await $.state.get(settingsNote)).value
    if (settings?.reopen === true) {
      await $.state.set(settingsNote, { ...settings, reopen: false })
      void $.ui.open(SETTINGS_OPEN).catch(() => undefined)
    }

    return next(e)
  })

  // House rules files already reported unreadable this load: each is toasted once.
  // ponytail: module state, lost on a reload, which toasts a missing file once more at worst.
  let missingRules: readonly string[] = []

  // A tracked skill moves or records the task, and its prompt carries the
  // task, the phase, the artifacts so far and what that skill can use.
  on('skill.prompt', async ($, e, next) => {
    // Unproven work does not move on: /pr, or any other stage, waits in the build stage, and the model is told what is missing.
    const before = await $.flow.task()
    const name = skillName(e.skill)
    // Diagnosing a failing build is part of building it: a move between build stages never waits.
    const isLeaving = before !== null && name !== before.phase && !BUILD.includes(name) && (name === 'pr' || name === 'push' || isStage(name, before))
    const root = await $.session.root()
    // Work already in the default branch leaves the pr or push stage nothing to do, proven here or not:
    // it steps aside through stage_done, the one path that records a stage and advances.
    const isShip = (name === 'pr' || name === 'push') && before !== null && stagesOf(before).includes(name)
    // ponytail: 10s a call, so an offline fetch or a gh waiting on auth delays the stage, never hangs it.
    const found = isShip ? await landed(argv => $.process.run(argv, { cwd: root, timeoutMs: 10_000 }).catch(() => undefined), name) : undefined
    if (found !== undefined && 'done' in found) {
      await $.flow.enter({ skill: e.skill })

      return next({ ...e, text: `flow: ${found.done}, so the ${name} stage has nothing to do. Run nothing else: call ${STAGE_DONE} with the summary "stepped aside: ${found.done}", then tell the person in one line, in plain text.` })
    }
    const held = before !== null && isLeaving ? leaveHold(before) : undefined
    if (held !== undefined) {
      return next({ ...e, text: held })
    }
    if (found !== undefined) {
      return next({ ...e, text: `flow: ${found.stop}. Tell the person that in one line, in plain text, and do not open a pull request.` })
    }
    if (before !== null && BUILD.includes(before.phase) && seenIn({ skill: skillName(e.skill) }) !== undefined) {
      await $.flow.note({ kind: 'seen', detail: 'verify' })
    }
    const task = await $.flow.enter({ skill: e.skill })
    if (task === null || !isTracked(e.skill, task)) {
      return next(e)
    }
    // The commit HEAD was at when this build stage started: the same on every re-entry, so the review range keeps earlier units.
    const started = BUILD.includes(name) ? stageStart(task) : undefined
    const [git, head] = await Promise.all([
      $.process.run(['git', 'branch', '--show-current'], { cwd: root }).catch(() => undefined),
      started === undefined ? undefined : $.process.run(['git', 'rev-list', '-1', '--abbrev-commit', `--before=@${Math.ceil(started / 1000)}`, 'HEAD'], { cwd: root }).catch(() => undefined),
    ])
    // The task's house rules ride on every stage skill, so a skill is adapted without forking it.
    const rules = task.rules === undefined ? undefined : await $.fs.read(task.rules.startsWith('/') ? task.rules : `${root}/${task.rules}`).catch(() => undefined)
    if (task.rules !== undefined && rules === undefined && !missingRules.includes(task.rules)) {
      missingRules = [...missingRules, task.rules]
      $.ui.toast(`flow: the house rules file ${task.rules} could not be read, so the stage runs without it.`)
    }
    // ponytail: the first 8,000 characters, so a long rules file cannot crowd out the skill.
    const rulesBlock =
      rules === undefined || rules.trim() === ''
        ? ''
        : `\n\nHouse rules for this task (${task.rules}), which win over the skill above where they disagree:\n${rules.trim().slice(0, 8000)}`

    const tracker = trackerOf(await $.fs.read(`${root}/${SETUP_FILE}`).catch(() => undefined))
    // The gates prefer an issue to a file of the same document in a repo that tracks work in issues.
    if ((tracker === 'github' || tracker === 'gitlab') && task.tracker !== tracker) {
      await $.flow.track({ tracker })
    }

    return next({ ...e, text: `${e.text}${rulesBlock}${ponytailNote(options.ponytail, name, BUILD)}\n\n${reminder(task, e.skill, git?.stdout.trim() ?? '', tracker, head?.exitCode === 0 ? head.stdout.trim() : '')}` })
  })

  // Planning phases hold code edits until /implement; /flow allow lifts it, and Jev, when on, lets a prototype through.
  on('tool.call', { tool: ['Write', 'Edit', 'NotebookEdit'] }, async ($, e, next) => {
    const task = await $.flow.task()
    const path = e.tool === 'NotebookEdit' ? e.notebook_path : e.file_path
    // Typed per tool when the build's tool inputs are declared, unknown otherwise.
    const rel = task === null || typeof path !== 'string' ? undefined : inside(await $.session.root(), path)
    const deny = task === null ? undefined : editGate(task, rel)
    if (deny !== undefined && task !== null && rel !== undefined) {
      const written = e.tool === 'Write' ? e.content : e.tool === 'Edit' ? e.new_string : e.new_source
      const waiver = await $.flow.waive({ block: 'edit', path: rel, text: typeof written === 'string' ? written : '' })
      if (waiver === null) {
        await $.flow.note({ kind: 'held', detail: rel })

        return { deny }
      }
    }
    const ran = await next(e)
    const isWritten = ran.deny === undefined && ran.isError === undefined
    const pointer = scratchPointer(rel)
    if (pointer !== undefined && isWritten) {
      await $.flow.produce({ pointer })
    }
    const seen = isWritten && task !== null && BUILD.includes(task.phase) ? seenIn({ pointer: rel }) : undefined
    if (seen !== undefined) {
      await $.flow.note({ kind: 'seen', detail: seen })
    }
    // A build stage's code edit needs a check after it: the first of a run of edits is stamped.
    if (task !== null && isWritten && isCode(rel) && rel !== undefined) {
      await $.flow.edited({ path: rel })
      await noteUndone($)
    }

    return ran
  })

  // A push or a pull request through an MCP server waits like one through Bash.
  // Every call that went through is also what Jev, when it is on, reads as the turn's evidence.
  on('tool.call', async ($, e, next) => {
    const open = e.tool.startsWith('mcp__') ? await $.flow.task() : null
    const deny = open === null ? undefined : shipHold(open, '', e.tool)
    if (deny !== undefined) {
      return { deny }
    }
    const done = await next(e)
    const path = e.tool === 'Write' || e.tool === 'Edit' ? e.file_path : e.tool === 'NotebookEdit' ? e.notebook_path : undefined
    observe(e, done.deny === undefined && done.isError !== true, typeof path === 'string' ? inside(await $.session.root(), path) : undefined)
    if (open !== null && done.deny === undefined && done.isError !== true) {
      await recordLinks($, mcpCreatedUrls(e.tool, 'method' in e ? e.method : undefined, done.text))
    }

    return done
  })

  // Checks become PR evidence and a build's proof; a created issue or PR becomes
  // an artifact, and a PR's CI is watched until it settles. A push or a PR waits
  // while the build is unproven.
  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const command = typeof e.command === 'string' ? e.command : ''
    const open = await $.flow.task()
    const deny = open === null ? undefined : shipHold(open, withoutBodies(command))
    if (deny !== undefined) {
      return { deny }
    }
    const ran = await next(e)
    if (ran.deny !== undefined) {
      return ran
    }
    const found = checksIn(command, checks)
    // The exit status speaks for a check only where nothing hides it: behind a pipe, `||` or `;` it is a
    // later command's either way, and in an `&&` chain a failure may be another command's own.
    for (const one of found.filter(one => !one.isMasked && (ran.isError !== true || one.isAlone))) {
      await $.flow.note({ kind: 'check', detail: one.command, ok: ran.isError !== true })
    }
    const check = found.find(one => one.isMasked)
    // A screenshot or output saved as the task's proof file counts as the change seen working.
    const seen = open !== null && BUILD.includes(open.phase) && ran.isError !== true ? seenIn({ command: withoutBodies(command) }) : undefined
    if (seen !== undefined) {
      await $.flow.note({ kind: 'seen', detail: seen })
    }
    await recordLinks($, createdUrls(command, ran.text))
    await noteUndone($)

    // Said now, not at stage_done: a build's check whose status was hidden proved nothing.
    return check !== undefined && open !== null && BUILD.includes(open.phase) ? { ...ran, context: [...(ran.context ?? []), maskedNote(check.command)] } : ran
  })

  // A typed /flow:<skill> alias runs the upstream skill itself. Its own prompt would ask the model to
  // launch it with the Skill tool, which the engine refuses for the skills only a person may run.
  // A stage typed with nothing after it is handed what the task holds for it, so the mod, not the
  // model, passes the work along: the ticket to the first stage, the spec to the tickets.
  on('command.run', async ($, e, next) => {
    const name = skillName(e.command)
    const open = e.args.trim() === '' ? await $.flow.task() : null
    const args = (open === null ? undefined : stageInput(open, name)) ?? e.args
    const upstream = e.command.startsWith('flow:') ? `${UPSTREAM}:${name}` : undefined
    // Only an alias has a namesake upstream: flow's own skills (recall, unslop, the principles) run as they are,
    // and with the upstream plugin missing the alias's own text says what to install.
    if (upstream === undefined || !(await $.command.list().catch(() => [])).some(one => one.name === upstream)) {
      return next(args === e.args ? e : { ...e, args })
    }
    // After this command answers: a command.run hook cannot run another command.
    $.clock.after(0, () => void $.command.run({ command: upstream, args }).catch(() => $.ui.toast(`flow: /${upstream} did not start. Type it in the prompt to run it.`)))

    return { text: `Running /${upstream}` }
  })

  on('command.run', { command: 'flow' }, async ($, e) => {
    const [, verb = '', rest = ''] = /^(\S*)\s*([\s\S]*)$/.exec(e.args.trim()) ?? []
    const open = await $.flow.task()

    // The board: the tasks, the open one's stages and what to do next.
    const docks = e.presentation.isFullscreen && e.presentation.columns >= 110
    if (verb === '') {
      await $.flow.show({ docks })

      return { text: open === null ? `No open task. /flow new <what are we doing> starts one.` : describe(open) }
    }

    if (verb === 'board') {
      await $.flow.show({ docks })
      const tasks = await $.flow.all()

      return {
        text:
          tasks.length === 0
            ? 'No tasks under .scratch/ yet.'
            : tasks
                .map(one => `${STATUS_LABEL[statusOf(one, false)]}  ${one.title}  (${one.slug})`)
                .join('\n'),
      }
    }

    if (verb === 'jev' && rest.trim() !== '') {
      const mode = rest.trim()
      if (!isJevMode(mode)) {
        return { text: `${mode} is not a Jev mode: off, shadow or on.` }
      }
      const row = await configRowOf(() => $.config.list(), 'jevMode')
      if ('refusal' in row) {
        return { text: `Jev stays ${jevMode}: ${row.refusal}.` }
      }
      const { deny } = await $.config.set({ key: row.key, value: mode }).catch((error: unknown) => ({ deny: error instanceof Error ? error.message : String(error) }))

      return { text: deny === undefined ? `Jev is now ${mode}. The mod reloads with it.` : `Jev stays ${jevMode}: ${deny}` }
    }

    if (verb === 'jev') {
      return { text: `Jev is ${jevMode}.\n${logSummary(parseLog(await $.store.get(LOG_KEY)))}` }
    }

    if (verb === 'share') {
      const link = rest.trim()
      if (link === '') {
        const url = await $.flow.board()

        return { text: url === null ? `No board yet.\n${USAGE}` : `Tasks go to ${url}` }
      }
      if (link === 'off') {
        await $.flow.share({ url: null })

        return { text: 'Stopped sending tasks to the board. What it shows stays until you delete the artifact.' }
      }
      if (!BOARD_LINK.test(link)) {
        return { text: 'That is not a claude.ai artifact link (https://claude.ai/.../artifact/...).' }
      }
      await $.flow.share({ url: link })
      const sent = await $.flow.sync({ tasks: await $.flow.all() })

      return { text: `Sent ${sent} task${sent === 1 ? '' : 's'} to ${link}. Each change follows a few seconds later.` }
    }

    const left = (task: FlowTask) => (open !== null && open.slug !== task.slug ? ` (${open.title} stays on disk)` : '')

    if (verb === 'new') {
      const { text, options, bad } = parseNew(rest)
      if (text === '' || bad !== undefined) {
        return { text: bad === undefined ? USAGE : `${bad} is not a value it takes.\n${USAGE}` }
      }
      const { task, isNew } = await $.flow.create({ text, ...defaults, ...options })
      if (docks) {
        await $.ui.open(RAIL_OPEN)
      }

      return { text: `${isNew ? 'Opened' : 'Resumed'}${left(task)}.\n${describe(task)}` }
    }

    if (verb === 'switch') {
      const existing = rest.trim() === '' ? null : await $.flow.load({ slug: rest.trim() })
      if (existing === null) {
        return { text: `No task at .scratch/${rest.trim()}/task.json. /flow board lists them.` }
      }
      const { closedAt: _, ...reopened } = existing
      await $.flow.save(reopened)
      await $.flow.suggest()

      return { text: `Switched to ${reopened.title}${left(reopened)}. ${nextLine(reopened)}` }
    }

    if (verb === 'why') {
      return { text: open === null ? 'No open task. /flow board lists them.' : explain(open, (await $.state.get(busyRef)).value ?? false) }
    }

    if (!['done', 'approve', 'allow', 'use', 'skip', 'followup'].includes(verb)) {
      return { text: USAGE }
    }
    if (open === null) {
      return { text: 'No open task.' }
    }

    if (verb === 'use') {
      const flow = rest.trim()
      if (!isFlow(flow)) {
        return { text: `Usage: /flow use ${FLOW_NAMES.join('|')}` }
      }
      const moved = recordEvent({ ...open, flow }, { kind: 'flow', detail: flow }, await $.clock.now())
      await $.flow.save(moved)

      return { text: `${open.title} now follows ${FLOWS[flow].label}.\n${describe(moved)}` }
    }

    // Gates wait for a person: a notification, a schedule, a peer or another plugin cannot pass one.
    const isPerson = PERSON.includes(e.origin.kind) || (e.origin.kind === 'plugin' && e.origin.name === 'flow')
    if ((verb === 'approve' || verb === 'allow' || verb === 'skip') && !isPerson) {
      return { text: `/flow ${verb} waits for a person; it was sent from ${e.origin.kind}.` }
    }

    // A person's call, like approve: the stage is recorded done, and approved or waived where it asks, as skipped.
    if (verb === 'skip') {
      const skipped = await $.flow.skip({ reason: rest })
      if (skipped === null) {
        return { text: `Nothing left to skip in ${open.title}. /flow done closes it.` }
      }
      await $.flow.suggest()

      return { text: `Skipped ${skipped.phase}. ${nextLine(skipped)}` }
    }

    if (verb === 'done') {
      return { text: await $.flow.close() }
    }

    if (verb === 'followup') {
      const fixes = await $.flow.followUp()

      return { text: fixes === null ? 'No retro findings to follow up. The retro writes them to .scratch/<slug>/retro.md.' : `Opened ${fixes.title}. ${nextLine(fixes)}` }
    }

    if (verb === 'allow') {
      if (allowPhase(open, 0) === open) {
        return { text: `Nothing is held in ${open.phase}.` }
      }
      await $.flow.allow({ reason: rest })

      return {
        text: PLANNING.includes(open.phase)
          ? `Code edits allowed for the rest of ${open.phase}.`
          : `Proof waived for the edits so far in ${open.phase}; the retro will see it.`,
      }
    }

    if (approvePhase(open, 0) === open) {
      return { text: `Nothing waits for approval in ${open.phase}.` }
    }
    // A person may name what they read: a spec written where the mod could not see it.
    const named = rest.trim() === '' ? open : ((await $.flow.produce({ pointer: rest.trim() })) ?? open)
    if (gateArtifact(named) === undefined) {
      return { text: `No ${GATED[open.phase]} recorded for ${open.phase}. /flow approve <path or link> names the one you read.` }
    }
    const moved = await $.flow.approve()
    const upNext = moved === null ? '' : ` Next: ${commandLine(moved)}`
    const percent = (await $.session.usage()).context.percent ?? 0
    // A gate is a phase boundary: the cheapest moment to /clear, so say so once, here.
    if (percent >= clearAt) {
      $.ui.toast(`Context ${Math.round(percent)}%: /clear, then${upNext.replace(' Next:', '')}. The task survives /clear.`)
    } else if (isAutoAdvance) {
      // After this command answers: a command.run hook cannot run another command.
      const expect = moved === null ? undefined : { slug: moved.slug, phase: moved.phase }
      $.clock.after(0, () => void $.flow.run({ expect }).catch((error: unknown) => $.ui.toast(`flow: the next stage did not start (${error instanceof Error ? error.message : String(error)}).`)))
    } else {
      await $.flow.suggest()
    }

    return { text: `Approved ${open.phase}.${upNext}` }
  })
}

