// ask_jev: the model puts questions to Jev about facts it passes in, and reads
// each answer with how sure Jev is. Not a gate: Jev's answer is never the
// person's approval. registerJudge registers the hook; register.tsx the tool.
import type { On, ToolSpec } from 'claude-code'

import type { JevMode } from '../types'
import { LOG_KEY, THRESHOLD, appended, askQuestions, askResults } from './jev'
import type { Asked, JevEntry } from './jev'

export const ASK_JEV = 'mcp__flow__ask_jev'
// The generated tool names list only the tools a session had; a pattern matches this one all the same.
const ASK_JEV_CALL = /^mcp__flow__ask_jev$/

const MAX_QUESTIONS = 8
const MAX_STATE = 8000
const ASK_TIMEOUT_MS = 10_000

export const ASK_JEV_TOOL: ToolSpec = {
  name: 'ask_jev',
  description: [
    "Ask Jev, TypeSafe's small judgment model, yes/no or pick-one questions about facts you pass in. Use it only when the person asked for Jev, or to settle a judgment call while grilling or planning.",
    'Put every fact the questions need in `state`: Jev judges those facts, not your framing, and sees nothing else.',
    `Each answer comes back with its probability and settled (true at ${THRESHOLD.settled} or more). Re-ask the unsettled ones with sharper facts, and stop when all are settled or a round adds nothing.`,
    "Jev's answer is advice for you. It is never the person's approval of a gate, a spec or tickets.",
  ].join(' '),
  inputSchema: {
    type: 'object',
    properties: {
      state: { type: ['object', 'string'], description: 'The facts the questions are judged on, as an object or plain text.' },
      questions: {
        type: 'array',
        maxItems: MAX_QUESTIONS,
        description: 'Up to 8. With options it is a pick-one question; without, a yes/no.',
        items: {
          type: 'object',
          properties: {
            id: { type: 'string', description: 'A short unique name for the answer.' },
            question: { type: 'string' },
            options: { type: 'array', items: { type: 'string' }, minItems: 2 },
          },
          required: ['id', 'question'],
        },
      },
    },
    required: ['state', 'questions'],
  },
}

const isRecord = (value: unknown): value is Record<string, unknown> => typeof value === 'object' && value !== null

/** The questions as asked, or why they cannot be. */
export const parseAsked = (raw: unknown): { asked: Asked[] } | { problem: string } => {
  if (!Array.isArray(raw) || raw.length === 0 || raw.length > MAX_QUESTIONS) {
    return { problem: `questions must be 1 to ${MAX_QUESTIONS} items of { id, question, options? }.` }
  }
  const asked = raw.flatMap((one: unknown): Asked[] => {
    if (!isRecord(one) || typeof one.id !== 'string' || one.id.trim() === '' || typeof one.question !== 'string' || one.question.trim() === '') {
      return []
    }
    const options = Array.isArray(one.options) ? one.options.filter((option): option is string => typeof option === 'string' && option !== '') : undefined

    return [{ id: one.id.trim(), question: one.question.trim(), ...(options === undefined ? {} : { options: [...new Set(options)] }) }]
  })
  if (asked.length !== raw.length || new Set(asked.map(one => one.id)).size !== asked.length) {
    return { problem: 'every question needs a unique non-empty id and a question.' }
  }

  return asked.some(one => one.options !== undefined && one.options.length < 2) ? { problem: 'options needs at least two choices.' } : { asked }
}

export const registerAsk = (on: On, mode: JevMode) => {
  on('tool.call', { tool: ASK_JEV_CALL }, async ($, call) => {
    const e: Record<string, unknown> = call
    if (mode === 'off') {
      return { result: 'Jev is unavailable: jevMode is off. Ask the person instead, or tell them /flow jev shadow turns it on.' }
    }
    const parsed = parseAsked(e.questions)
    if ('problem' in parsed) {
      return { result: `Not asked: ${parsed.problem}` }
    }
    const state: unknown = typeof e.state === 'string' ? e.state.trim() : e.state
    if (state === undefined || state === '' || state === null || JSON.stringify(state).length > MAX_STATE) {
      return { result: `Not asked: pass the facts in state, as an object or text of at most ${MAX_STATE} characters.` }
    }
    const questions = askQuestions(parsed.asked)
    const started = await $.clock.now()
    const answers = await $.flow.judge({ state, questions, timeoutMs: ASK_TIMEOUT_MS })
    if (answers === null) {
      return { result: 'Jev is unavailable: there is no TYPESAFE_API_KEY (or jevApiKey), or the call failed or ran late. Ask the person instead.' }
    }
    const results = askResults(questions, answers)
    const task = await $.flow.task()
    const entry: JevEntry = {
      at: started,
      call: 'ask',
      ms: (await $.clock.now()) - started,
      slug: task?.slug ?? '',
      phase: task?.phase ?? '',
      answers,
      note: `${results.length} asked, ${results.filter(one => one.settled).length} settled`,
    }
    await $.store.set(LOG_KEY, appended(await $.store.get(LOG_KEY), entry)).catch(() => undefined)

    return { result: JSON.stringify({ settled: results.every(one => one.settled), results }) }
  })
}

