// Autonomy: the model reports a stage finished, the mod advances when that is
// safe, tells the person when a gate waits, and runs the task on its own
// model and effort. The noun's run enters a task's worktree.
import type { AgentSpawnInput, EngineInterface, On, ToolSpec } from 'claude-code'

import type { FlowEffort, FlowTask } from '../types'
import { GATED, PLANNING, gateArtifact, isIssue, isPassed, isWaived, nextAction, stagesOf } from './flow'
import { MODELS, commandOf, missingNotice, resolveCommand, standIn, standInNotice } from './flows'
import { BUILD, isProven, judgedGap, proofGap, stuckReason } from './proof'
import { DOC, baseName } from './doc'
import { commandLine } from './ui'
import { wantedOf } from './status'

// The validator lists state reads per file, so each file spells its reference.
const current = { plugin: 'flow', key: 'task' } as const
const advance = { plugin: 'flow', key: 'advance' } as const

export const STAGE_DONE = 'mcp__flow__stage_done'

/** The tool the model calls when a stage's work is finished. register.tsx registers it at session.start: one hook per event. */
export const STAGE_DONE_TOOL: ToolSpec = {
  name: 'stage_done',
  description:
    "Call this once when the work of the current flow stage is finished (not after each question), with a one-line summary of what was done. The flow mod records it and answers with the task's next step. A build stage is recorded only once its checks pass. Call it with outcome 'blocked' when you cannot finish without the person.",
  inputSchema: {
    type: 'object',
    properties: {
      summary: { type: 'string', description: 'One line: what this stage did, or what blocks it.' },
      decisions: {
        type: 'array',
        items: { type: 'string' },
        description:
          'Optional: the forks this stage settled that a reviewer would ask about, one line each: what was chosen, why, and the evidence (a path, a commit, a command). Only real decisions, at most 5.',
      },
      outcome: { type: 'string', enum: ['done', 'blocked'], description: 'done (the default), or blocked: the stage cannot finish without the person.' },
    },
    required: ['summary'],
  },
}

/** Finished phases whose next stage may start on its own: building and closing. */
export const AUTO_FROM: readonly string[] = ['implement', 'implement-spec', 'diagnosing-bugs', 'pr', 'push']

/**
 * A planning stage that leads to another planning stage (grill-with-docs to to-spec, the chart to
 * the clearing, a spec whose gate Jev waived to the tickets): never a gate a person still holds,
 * never the clearing loop, never into a build.
 */
const isPlanningStep = (task: FlowTask) =>
  PLANNING.includes(task.phase) &&
  (!(task.phase in GATED) || isWaived(task)) &&
  task.phase !== 'wayfinder-clear' &&
  PLANNING.includes(nextAction(task).stage ?? '')

/** Whether the stage after the task's finished phase may start without a person: a stage, not a gate or the close. */
export const canAutoAdvance = (task: FlowTask) =>
  (AUTO_FROM.includes(task.phase) || isPlanningStep(task)) && nextAction(task).command !== 'flow' && isProven(task) && judgedGap(task) === undefined && stuckReason(task) === undefined

/** What stage_done answers in place of recording, while a build stage's edits are unproven. */
export const unprovenAnswer = (task: FlowTask) => {
  const gap = proofGap(task)

  return gap === undefined
    ? undefined
    : [
        `flow: not recorded. ${task.phase} is not proven: ${gap}.`,
        'Run the project checks (tests, typecheck, lint) and show the change working, then call this tool again. A check piped into another command or followed by `|| true` is not counted.',
        'If a check fails, reproduce it and fix the root cause (diagnosing-bugs) before patching.',
        "If you ran this repo's check and it passed but was not counted, call this tool with outcome 'blocked' and name the command, so the person can add it to the checks option or allow.",
      ].join(' ')
}

/** The decisions a stage_done call reported, as the log keeps them: lines of text, at most five, each cut to 200 characters. */
export const decisionsOf = (reported: unknown) =>
  (Array.isArray(reported) ? reported : [])
    .filter((one): one is string => typeof one === 'string' && one.trim() !== '')
    .slice(0, 5)
    .map(one => one.trim().slice(0, 200))

/** What the second look is asked: one thing, or that there is nothing. */
export const criticPrompt = (task: FlowTask) =>
  [
    `Before the ${task.phase} stage of "${task.title}" is recorded finished, look back over the work in this conversation as a strict reviewer.`,
    'Name the single most important thing that is likely missing or wrong: an untested path, a requirement skipped, a caller not updated, a check that proves less than it seems.',
    'One or two sentences, no preamble. If nothing material is missing, reply exactly: Nothing material.',
  ].join(' ')

/** What the critic said that the model must answer, or undefined when it found nothing or could not say. */
// ponytail: cut at 600 characters so a rambling fork cannot flood the tool result.
export const criticFinding = (reply: { isAnswered: boolean; text?: string } | undefined) => {
  const said = reply?.isAnswered === true ? (reply.text ?? '').trim() : ''

  return said === '' || /^nothing material/i.test(said) ? undefined : said.slice(0, 600)
}

/**
 * What the second reviewer, on another model, is asked. It sees the change, not the conversation,
 * and judges the first reviewer's finding before naming its own: agreement between two models is
 * the signal, a finding only one raises is a note.
 */
export const panelPrompt = (task: FlowTask, summary: string, diff: string, finding: string | undefined) =>
  [
    `You are the second reviewer of the ${task.phase} stage of "${task.title}". Its author reports: ${summary === '' ? 'no summary' : summary}.`,
    finding === undefined ? 'The first reviewer found nothing material.' : `The first reviewer said: ${finding}`,
    'Reply with exactly two lines and nothing else.',
    finding === undefined
      ? 'Line 1: NONE'
      : "Line 1: AGREE if the first reviewer's point is real and worth fixing before this ships, else DISAGREE.",
    'Line 2: MISSED: the single most important thing likely missing or wrong that the first reviewer did not name, in one or two sentences, or MISSED: nothing.',
    'The change, as git diff against the branch base:',
    diff === '' ? '(no diff could be read)' : diff,
  ].join('\n')

/** The second reviewer's reply read as a verdict, or undefined when it did not answer in the asked form. */
export const panelVerdict = (text: string) => {
  const first = /^\s*(AGREE|DISAGREE|NONE)\b/im.exec(text)?.[1]?.toUpperCase()
  if (first === undefined) {
    return undefined
  }
  const missed = /MISSED:\s*(.+)/i.exec(text)?.[1]?.trim()

  return { isAgreed: first === 'AGREE', ...(missed === undefined || missed === '' || /^nothing\b/i.test(missed) ? {} : { missed: missed.slice(0, 600) }) }
}

/**
 * What the reviews mean for the report: the finding both reviewers stand behind holds it, a finding
 * only one raised is kept as a note. With no second reviewer, or none that answered, the fork's
 * finding holds as it always did.
 */
export const criticOutcome = (finding: string | undefined, verdict: ReturnType<typeof panelVerdict>, model: string) => {
  if (verdict === undefined) {
    return { hold: finding, notes: [] as string[] }
  }
  const notes = [
    ...(finding !== undefined && !verdict.isAgreed ? [`only the session's fork raised this, ${model} disagreed: ${finding}`] : []),
    ...(verdict.missed === undefined ? [] : [`only ${model} raised this: ${verdict.missed}`]),
  ]

  return { hold: finding !== undefined && verdict.isAgreed ? `${finding} (${model} agreed)` : undefined, notes }
}

// ponytail: 30,000 characters of the diff; a reviewer that needs more reads a summary, not this.
const DIFF_MOST = 30_000

/** The change under review: `git diff` against where the branch left the default one, else against HEAD, plus untracked files by name. */
const branchDiff = async ($: EngineInterface) => {
  const cwd = await $.session.root()
  const git = (args: string[]) => $.process.run(['git', ...args], { cwd }).then(ran => (ran.exitCode === 0 ? ran.stdout : ''), () => '')
  const base = (await git(['merge-base', 'HEAD', 'origin/HEAD'])).trim() || 'HEAD'
  const untracked = (await git(['ls-files', '--others', '--exclude-standard'])).trim()

  return `${(await git(['diff', base])).slice(0, DIFF_MOST)}${untracked === '' ? '' : `\nUntracked files:\n${untracked}`}`.trim()
}

/** Whether a build stage asks the critic before it is recorded: once per stage name, so a second round of the same stage is not looked at again. */
export const needsCritic = (task: FlowTask) =>
  task.critic === true && BUILD.includes(task.phase) && !task.log.some(one => one.kind === 'critic' && one.phase === task.phase)

/** The commands a task's stages run that no installed skill provides, in stage order; none when the list could not be read. */
export const missingStages = (task: FlowTask, installed: readonly string[]) =>
  installed.length === 0 ? [] : [...new Set(stagesOf(task).map(commandOf))].filter(command => resolveCommand(installed.map(name => ({ name })), command) === undefined)

/** The commands a task's stages run that another plugin's skill answers, with the skill, in stage order. */
export const standInStages = (task: FlowTask, installed: readonly string[]) => {
  const listed = installed.map(name => ({ name }))

  return [...new Set(stagesOf(task).map(commandOf))].flatMap(command => {
    const name = standIn(listed, command)

    return name === undefined ? [] : [{ command, name }]
  })
}

/** A turn that ends on a question waits for its answer, whatever it reported. */
export const endsOnQuestion = (answer: string) => /\?["')\]*_`]*\s*$/.test(answer)

/** What a person should be told when a gated phase waits for them, or undefined when nothing waits. */
export const gateNotice = (task: FlowTask) => {
  const what = GATED[task.phase]
  if (what === undefined || isPassed(task)) {
    return undefined
  }
  const made = gateArtifact(task)?.pointer ?? `.scratch/${task.slug}/`

  return `flow: the ${what} ${what === 'tickets' ? 'are' : 'is'} ready. Read ${made}, then /flow approve`
}

/**
 * The model id a turn step can name. `turn.step` does not resolve aliases
 * (measured: `haiku` fails the request), so a full id passes, a known alias
 * becomes its id, and any other word resolves only to the session's own
 * model when it names that family.
 */
export const modelId = (wanted: string, session: string) =>
  wanted.includes('claude-')
    ? wanted
    : (MODELS.find(one => one.alias === wanted)?.id ?? (session.includes(wanted) ? session : undefined))

export { wantedOf }

/** What to rewrite on a step, and the model that could not be resolved. */
export const overrideOf = (task: FlowTask, session: string): { model?: string; effort?: FlowEffort; unresolved?: string } => {
  const wanted = wantedOf(task)
  const model = wanted.model === undefined ? undefined : modelId(wanted.model, session)

  return {
    ...(model === undefined ? {} : { model }),
    ...(wanted.effort === undefined ? {} : { effort: wanted.effort }),
    ...(wanted.model !== undefined && model === undefined ? { unresolved: wanted.model } : {}),
  }
}

/** The status line while a task overrides the session's model or effort; the engine leads it with the plugin's name. */
export const overrideLabel = (model: string | undefined, effort: FlowEffort | undefined) =>
  model === undefined && effort === undefined
    ? undefined
    : [model, effort === undefined ? undefined : model === undefined ? `${effort} effort` : `at ${effort}`].filter(Boolean).join(' ')

// ponytail: matched by name; an agent file that reuses one of these names is routed too.
/** The engine's own helper agents, which carry no model of their own; an agent someone defined keeps the one it set. */
const BUILT_IN = ['Explore', 'general-purpose', 'Plan']

/**
 * The model a built-in helper agent runs on under the task's `helpers`: the current stage's model,
 * or Sonnet throughout. An alias passes as it is, so the engine resolves it to its latest; a full
 * id passes too. Undefined leaves the spawn as it was, as any other word does: turn.step toasts
 * that one for the main loop.
 */
export const helperModel = (task: FlowTask | null, spawn: Pick<AgentSpawnInput, 'subagentType' | 'fork' | 'model'>) =>
  task?.helpers === undefined || spawn.fork || spawn.model !== undefined || !BUILT_IN.includes(spawn.subagentType)
    ? undefined
    : spawnable(task.helpers === 'stage' ? wantedOf(task).model : task.helpers)

/** A model word agent.spawn takes: a known alias or a full id. */
const spawnable = (model: string | undefined) =>
  model !== undefined && (model.includes('claude-') || MODELS.some(one => one.alias === model)) ? model : undefined

/** `off`, or the model a second reviewer runs on beside the session's fork. */
type Options = { isAutoAdvance: boolean; clearAt: number; criticPanel: string }

export const registerAutonomy = (on: On, { isAutoAdvance, clearAt, criticPanel }: Options) => {
  // Notices already shown, by task and phase. Lost on a reload, which shows one again at worst.
  let told: readonly string[] = []
  const firstTime = (key: string) => {
    if (told.includes(key)) {
      return false
    }
    told = [...told, key]

    return true
  }
  // The status line this hook drew, so it clears only its own.
  let shown: string | undefined

  on('tool.call', { tool: STAGE_DONE }, async ($, e) => {
    const summary = typeof e.summary === 'string' ? e.summary.trim().slice(0, 200) : ''
    const open = await $.flow.task()
    // The forks the stage settled outlive the routine facts in the log, for the retro and the PR: kept
    // only once the report is, so a refused report sent again does not log them twice.
    const keepDecisions = async () => {
      for (const decision of decisionsOf(e.decisions)) {
        await $.flow.note({ kind: 'decision', detail: decision })
      }
    }
    if (open !== null && e.outcome === 'blocked') {
      await keepDecisions()
      await $.flow.note({ kind: 'blocked', ...(summary === '' ? {} : { detail: summary }) })
      $.ui.toast(`flow: ${open.phase} is blocked${summary === '' ? '' : `: ${summary}`}`)

      return { result: 'The flow mod recorded that the stage is blocked. Stop here and tell the person what you need from them.' }
    }
    // A build stage is finished on evidence, not on the model's word: it is still mid-turn, so it can go and get it.
    // In a task that never ran a check, Jev may judge the change seen working in place of one.
    const proven = open !== null && unprovenAnswer(open) !== undefined && (await $.flow.waive({ block: 'proof', summary })) !== null ? await $.flow.task() : open
    const refusal = proven === null ? undefined : unprovenAnswer(proven)
    if (refusal !== undefined) {
      return { result: refusal }
    }
    // A proven build gets one second look per stage, from a fork that shares the session's cache,
    // and with criticPanel set a second reviewer on another model that judges the fork's finding.
    if (open !== null && needsCritic(open)) {
      const finding = criticFinding(await $.model.fork({ prompt: criticPrompt(open) }).catch(() => undefined))
      const reply =
        criticPanel === 'off'
          ? undefined
          : await $.model
              .complete({ model: criticPanel, prompt: panelPrompt(open, summary, await branchDiff($), finding), maxTokens: 600, timeoutMs: 90_000 })
              .catch(() => undefined)
      const outcome = criticOutcome(finding, reply?.isAnswered === true ? panelVerdict(reply.text) : undefined, criticPanel)
      for (const note of outcome.notes) {
        await $.flow.note({ kind: 'critic', detail: note })
      }
      if (outcome.hold !== undefined) {
        await $.flow.note({ kind: 'critic', detail: outcome.hold })

        return {
          result: `flow: not recorded yet. A second look at the work: ${outcome.hold} If it is real, fix it and re-run the checks; if not, say why in one line. Then call this tool again.`,
        }
      }
    }
    // A gate's document is finished: Jev may judge that no person needs to read it first.
    await keepDecisions()
    const waiver = open !== null && open.phase in GATED && !isPassed(open) ? await $.flow.waive({ block: 'gate' }) : null
    const task = await $.flow.note({ kind: 'done', ...(summary === '' ? {} : { detail: summary }) })
    if (task === null) {
      return { result: 'flow: no task is open, so nothing was recorded.' }
    }
    if (waiver !== null) {
      $.ui.toast(`flow: ${waiver.detail}, so the ${GATED[task.phase] ?? 'gate'} needs no approval. /flow doc reads it; /flow approve is still yours.`)
    }
    const line = commandLine(task)
    const notice = gateNotice(task)
    if (notice !== undefined && firstTime(`${task.slug}:${task.phase}`)) {
      $.ui.toast(notice)
    }
    // A second report in the same phase never advances twice.
    const isFirst = task.log.filter(one => one.kind === 'done' && one.phase === task.phase).length === 1
    // The next stage waits for this turn to answer, so it never starts mid-turn.
    if (isAutoAdvance && isFirst && canAutoAdvance(task)) {
      await $.state.set(advance, true)
    }

    const waived = waiver === null ? '' : ` ${waiver.detail}, so the ${GATED[task.phase] ?? 'gate'} needs no approval.`
    const recorded = `The flow mod recorded that ${task.phase} is finished.${waived} Next for the task: ${line} (${nextAction(task).why}).`
    const ending = isAutoAdvance && isFirst && canAutoAdvance(task)
      ? 'The flow mod starts it once this turn answers; do not start it yourself, and do not end your turn on a question.'
      : `The flow mod will not start it, and you must not either. End your turn by telling the person the command to type, in plain text, not a code block: ${line}`

    return { result: `${recorded} ${ending}` }
  })

  // A turn that answered runs the stage its stage_done left waiting; one aborted, refused or failed drops it.
  on('turn.complete', { reason: ['answer', 'aborted', 'refusal', 'error'] }, async ($, e, next) => {
    const done = await next(e)
    if (e.agentId !== undefined || (await $.state.get(advance)).value !== true) {
      return done
    }
    await $.state.set(advance, false)
    const task = (await $.state.get(current)).value ?? null
    if (e.reason !== 'answer' || task === null || !canAutoAdvance(task) || endsOnQuestion(e.answer)) {
      return done
    }
    const percent = (await $.session.usage()).context.percent ?? 0
    if (percent >= clearAt) {
      $.ui.toast(`Context ${Math.round(percent)}%: /clear, then ${commandLine(task)}. The task survives /clear.`)
    } else {
      const expect = { slug: task.slug, phase: task.phase }
      $.clock.after(0, () => void $.flow.run({ expect }).catch((error: unknown) => $.ui.toast(`flow: the next stage did not start (${error instanceof Error ? error.message : String(error)}).`)))
    }

    return done
  })

  // A new task whose workflow runs skills nobody installed says so now, not when the stage comes.
  on('flow.create', async ($, e, next) => {
    const made = await next(e)
    if (made.deny === undefined && made.value.isNew) {
      const installed = (await $.command.list().catch(() => [])).map(one => one.name)
      const missing = missingStages(made.value.task, installed)
      if (missing.length > 0) {
        $.ui.toast(missingNotice(missing))
      }
      const standing = standInStages(made.value.task, installed)
      if (standing.length > 0) {
        $.ui.toast(standInNotice(standing))
      }
    }

    return made
  })

  // A gated phase that just got its artifact waits for a person: say so once, and put the artifact
  // beside the transcript. Opened unasked, the tab seats only where it docks, and never takes the keys.
  on('flow.produce', async ($, e, next) => {
    const ran = await next(e)
    const task = ran.deny === undefined ? ran.value : null
    const notice = task === null ? undefined : gateNotice(task)
    const made = task === null ? undefined : gateArtifact(task)
    if (task !== null && notice !== undefined && firstTime(`${task.slug}:${task.phase}`)) {
      $.ui.toast(notice)
      if (made !== undefined && (!made.pointer.startsWith('http') || isIssue(made.pointer))) {
        await $.flow.doc({ pointer: made.pointer })
        await $.ui.open({ id: DOC, title: baseName(made.pointer) }).catch(() => undefined)
      }
    }

    return ran
  })

  // The task's helper agents run on the model for their role.
  on('agent.spawn', async ($, e, next) => {
    const task = (await $.state.get(current)).value ?? null
    const model = helperModel(task, e)

    return next(model === undefined ? e : { ...e, model })
  })

  // The main loop runs on the open task's model and effort; subagents keep theirs.
  on('turn.step', async function* ($, e, next) {
    if (e.agentId !== undefined) {
      return yield* next(e)
    }
    const task = (await $.state.get(current)).value ?? null
    const set = task === null ? {} : overrideOf(task, wantedOf(task).model === undefined ? '' : await $.session.model())
    const label = overrideLabel(set.model, set.effort)
    if (label !== shown) {
      shown = label
      $.ui.status(label)
    }
    if (set.unresolved !== undefined && task !== null && firstTime(`${task.slug}:model:${set.unresolved}`)) {
      $.ui.toast(
        `flow: "${set.unresolved}" is not a full model id, so this task keeps the session's model. Use an id like claude-sonnet-5-5.`,
      )
    }

    return yield* next({
      ...e,
      ...(set.model === undefined ? {} : { model: set.model }),
      ...(set.effort === undefined ? {} : { effort: set.effort }),
    })
  })
}

files.hooks/dialog.tsx:
// The new-task dialog: /flow new with no text opens it as a pane. The fields
// live in the `draft` state; draft.ts holds what typing and picking do to it.
import { update } from 'claude-code'
import type { On, Timer } from 'claude-code'

import type { FlowDefaults, FlowDraft, JevMode } from '../types'
import {
  attachment,
  blurbOf,
  blankDraft,
  blocker,
  briefOf,
  createFrom,
  HELPERS,
  effortOf,
  flowLabels,
  flowOfLabel,
  githubRef,
  guessed,
  helpersOf,
  issueOf,
  judged,
  modelsSummary,
  named,
  optionsSummary,
  picked,
  preview,
  previewLegend,
  slugPath,
  typed,
} from './draft'
import type { Brief, Issue } from './draft'
import { FINISH_LABEL, PLANNING, nextAction, nextFinish } from './flow'
import { EFFORTS, FLOWS, FLOW_NAMES, MODELS } from './flows'
import { BRIEF, LOG_KEY, LOG_SIZE, briefState, parseLog, verdictOf } from './jev'
import { COLUMN_PX, GATE, PROOF, stripAlt, stripSvg } from './strip'
import { SHORT } from './ux'
import { RAIL_OPEN, keyed as keyLabel } from './status'

// The validator lists state reads per file, so each file spells its reference.
const draft = { plugin: 'flow', key: 'draft' } as const

export const DIALOG = 'flow-new'

/** How the form opens: it takes the keys, Esc cancels it, and it asks for the rows it needs inline above the prompt. */
export const DIALOG_OPEN = { id: DIALOG, title: 'New task', focus: true, closeOnEscape: true, holdToasts: true, rows: 26 } as const

/** How long the text rests before Jev reads it. */
const PAUSE_MS = 1500

// ponytail: module state, as ui.tsx keeps the mode: the pending pause and the last text Jev read; a reload just reads once more.
let pause: Timer | undefined
let weighed = ''

export const registerDialog = (on: On, defaults: FlowDefaults, jev: JevMode) => {
  // No text and no flags opens the form; a surface without fields, and anything else, is the main hook's.
  on('command.run', { command: 'flow' }, async ($, e, next) => {
    if (e.args.trim() !== 'new' || !(await $.session.surfaces()).some(surface => surface !== 'mobile')) {
      return next(e)
    }
    await $.state.set(draft, blankDraft(defaults))
    weighed = ''
    const opened = await $.ui.open(DIALOG_OPEN)

    return { text: opened.isPlaced ? 'New task dialog opened.' : `Could not seat the new task dialog: ${opened.reason}` }
  })

  // Esc and the close mark end the draft too.
  on('ui.close', { id: DIALOG }, async ($, e, next) => {
    const closed = await next(e)
    await $.state.set(draft, null)

    return closed
  })

  on('ui.render', { component: 'Pane', requestId: DIALOG }, async ($, e) => {
    const current = (await $.state.get(draft)).value ?? null
    if (e.surface === 'mobile') {
      const { Text } = $.ui.resolve(e)

      return <Text dimColor>The new task dialog needs a field to type in. Use /flow new &lt;what are we doing&gt;.</Text>
    }
    const { Box, Button, Input, Select, Text } = $.ui.resolve(e)
    const keyed = (key: string, label: string) => keyLabel(e.surface, key, label)
    if (current === null) {
      return <Text dimColor>Closed. /flow new opens it again.</Text>
    }
    const d: FlowDraft = current
    const session = await $.session.model().catch(() => '')
    const why = blocker(d)
    const stages = preview(d)
    const fieldWidth = Math.max(20, e.props.bodyColumns - 2)
    const legend = previewLegend(stages, d.ui)
    // Surfaces that draw SVG get the strip as a picture.
    const svgOf = (segments: typeof stages) => {
      if (e.surface === 'terminal') {
        return null
      }
      const { Svg } = $.ui.resolve(e)

      return <Svg source={stripSvg(segments, e.props.bodyColumns * COLUMN_PX)} alt={stripAlt(segments)} />
    }
    const edit = (change: (from: FlowDraft) => FlowDraft) => update($, draft, from => (from ? change(from) : null))
    // Moving the ring is a nicety: a pane that closed meanwhile is no failure.
    const focus = (key: string) => $.ui.focus({ requestId: DIALOG, key }).catch(() => undefined)
    // The ui.close hook clears the draft for Esc; a close the dialog makes clears it here as well.
    const close = async () => {
      await $.ui.close({ id: DIALOG })
      await $.state.set(draft, null)
    }

    // The brief a pasted `@<path>` names: the file's contents, or undefined for other text and a file that cannot be read.
    const readBrief = async (text: string): Promise<Brief | undefined> => {
      const at = attachment(text)
      if (at === undefined) {
        return undefined
      }
      const path = at.path.startsWith('/') ? at.path : `${await $.session.root()}/${at.path}`
      const contents = await $.fs.read(path).catch(() => undefined)

      return typeof contents === 'string' ? briefOf(contents, at.note) : undefined
    }

    // Read the text once it is settled (Enter, or a pause): name the task from a brief file, refine the guessed
    // workflow with the classifier, and ask Jev for the flow, the UI and what is missing. Fail open at every step;
    // a picked flow is never moved. In shadow Jev's read is logged and nothing shows.
    const weigh = async (text: string) => {
      const one = text.trim()
      const brief = one === '' ? undefined : await readBrief(text)
      const words = brief?.body ?? one
      if (words === '' || githubRef(text) !== undefined || words === weighed) {
        return
      }
      weighed = words
      const isUnpicked = (await $.state.get(draft)).value?.isFlowPicked === false
      if (brief !== undefined) {
        await edit(from => (from.text === text ? named(from, brief) : from))
      }
      const started = await $.clock.now()
      const [label, answers] = await Promise.all([
        isUnpicked ? $.model.classify(words, flowLabels, { model: 'haiku' }).catch(() => undefined) : undefined,
        $.flow.judge({ state: briefState(words), questions: BRIEF }),
      ])
      const flow = flowOfLabel(label)
      const verdict = answers === null ? undefined : verdictOf(answers)
      if (answers !== null) {
        const note = verdict === undefined ? '' : `${verdict.flow ?? 'no flow'}${verdict.isUi ? ' ui' : ''}${verdict.hint === undefined ? '' : ' unclear'}`
        const entry = { at: started, call: 'brief', ms: (await $.clock.now()) - started, slug: '', phase: 'new', answers, note }
        await $.store.set(LOG_KEY, [...parseLog(await $.store.get(LOG_KEY)), entry].slice(-LOG_SIZE)).catch(() => undefined)
      }
      // The text moved on while Jev read: its answer is about words no longer there.
      await edit(from => {
        const guess = flow === undefined ? from : guessed(from, flow)

        return from.text !== text ? guess : jev === 'on' && verdict !== undefined ? judged(guess, verdict) : guess
      })
    }

    // Enter on the description: read it now, and move on to the name.
    const submitWhat = async (text: string) => {
      pause?.cancel()
      await focus('name')
      await weigh(text)
    }
    // Typing on: read it once it rests, so a keystroke is never a request.
    const typedWhat = (text: string) => {
      void edit(from => typed(from, text))
      pause?.cancel()
      pause = text.trim() === '' ? undefined : $.clock.after(PAUSE_MS, () => void weigh(text))
    }

    const create = async () => {
      const now = (await $.state.get(draft)).value ?? null
      if (now === null || blocker(now) !== undefined) {
        return
      }
      const ref = githubRef(now.text)
      let issue: Issue | undefined
      if (ref !== undefined) {
        const cwd = await $.session.root()
        const ran = await $.process
          .run(['gh', 'issue', 'view', ref, '--json', 'title,body,url'], { cwd })
          .catch((error: unknown) => (error instanceof Error ? error.message : 'gh did not run'))
        const read = typeof ran === 'string' ? ran : issueOf(ran)
        if (typeof read === 'string') {
          $.ui.toast(`flow could not read issue ${ref}: ${read}`)

          return
        }
        issue = read
      }
      const brief = ref === undefined ? await readBrief(now.text) : undefined
      await close()
      const { task } = await $.flow.create(createFrom(now, issue, brief))
      // Beside the transcript the board keeps the stages in view; inline it would only crowd the prompt.
      if (e.props.placement === 'dock') {
        await $.ui.open(RAIL_OPEN)
      }
      if (task.phase !== 'new') {
        $.ui.toast(`Resumed ${task.title} (${task.phase})`)

        return
      }
      $.ui.toast(`Opened ${task.title}: starting /${nextAction(task).command}`)
      await $.flow.run()
    }

    // Each workflow on its own row in plain words; the one picked opens into its stages as cards.
    // As a Mermaid flowchart would draw them: one direction, short labels, and colour only where it
    // means something: a gate you approve, and the build that needs proof.
    // A card keeps its gate mark and the arrow after it in one unit that never shrinks, so a narrow row wraps between cards.
    const cards = (
      <Box flexWrap="wrap" alignItems="center">
        {stages.map((one, at) => (
          <Box key={`card-${one.stage}`} alignItems="center" flexShrink={0}>
            <Box borderStyle="round" borderColor={one.gate !== undefined ? 'warning' : one.proof !== undefined ? 'permission' : 'inactive'} paddingX={1} flexShrink={0}>
              <Text wrap="truncate-end">
                {SHORT[one.stage] ?? one.label}
                {one.gate !== undefined ? <Text color="warning">{` ${GATE}`}</Text> : null}
                {one.proof !== undefined ? <Text color="permission">{` ${PROOF.ahead}`}</Text> : null}
              </Text>
            </Box>
            {at === stages.length - 1 ? null : <Text dimColor>{' → '}</Text>}
          </Box>
        ))}
      </Box>
    )
    const hasPlanning = stages.some(one => PLANNING.includes(one.stage))
    const modelOptions = [
      { value: '', label: session === '' ? 'Session default' : `Session default (${session})` },
      ...MODELS.map(one => ({ value: one.alias, label: one.label })),
    ]
    const effortOptions = [{ value: '', label: 'Session default' }, ...EFFORTS.map(value => ({ value, label: value }))]
    const optionsLine = optionsSummary(d)
    const modelsLine = modelsSummary(d, hasPlanning)
    // A section's toggle, and while it is folded, the line of what it is set to.
    const section = (name: 'options' | 'models', label: string, hotkey: string, folded: string) => (
      <Box columnGap={2}>
        <Button
          key={name}
          label={d.openSection === name ? `Hide ${label.toLowerCase()}` : label}
          hotkey={hotkey}
          plain
          onPress={() => edit(from => ({ ...from, openSection: from.openSection === name ? undefined : name }))}
        />
        {d.openSection === name ? null : <Text dimColor wrap="truncate-end">{folded}</Text>}
      </Box>
    )
    // The picked workflow leads, with its stages as cards; the others wait in one quiet row.
    const flowButton = (name: (typeof FLOW_NAMES)[number], at: number) => (
      <Button
        key={`flow-${name}`}
        label={`${d.flow === name ? '▸ ' : ''}${FLOWS[name].label}`}
        hotkey={String(at + 1)}
        plain
        dimColor={d.flow !== name}
        onPress={() => edit(from => picked(from, name))}
      />
    )
    // Every workflow as a tab, the picked one open below it in a frame: what it is for, its stages as
    // cards, and what they ask of you. b and n step through them; a digit jumps to one.
    const at = FLOW_NAMES.indexOf(d.flow)
    const step = (by: number) => edit(from => picked(from, FLOW_NAMES[(FLOW_NAMES.indexOf(from.flow) + by + FLOW_NAMES.length) % FLOW_NAMES.length] ?? from.flow))
    const gates = stages.filter(one => one.gate !== undefined).length
    const counts = stages.length === 0 ? 'No fixed stages: every skill you run is recorded.' : `${stages.length} stages${gates === 0 ? '' : `, ${gates} you approve`}`
    const flowRows = (
      <Box flexDirection="column">
        <Box flexWrap="wrap" columnGap={2}>
          {FLOW_NAMES.map((name, index) => flowButton(name, index))}
        </Box>
        <Box flexDirection="column" borderStyle="round" borderColor="inactive" borderDimColor paddingX={1}>
          <Box columnGap={2}>
            <Button key="flow-prev" label="‹" hotkey="b" plain dimColor onPress={() => step(-1)} />
            <Text bold>{`${FLOWS[d.flow].label.toUpperCase()} WORKFLOW`}</Text>
            <Text dimColor>{`${at + 1} of ${FLOW_NAMES.length}`}</Text>
            {d.isFlowPicked ? null : <Text color="claude" bold>Suggested</Text>}
            <Button key="flow-next" label="›" hotkey="n" plain dimColor onPress={() => step(1)} />
          </Box>
          <Text wrap="wrap">{`${blurbOf(d)}.`}</Text>
          {e.surface === 'terminal' && stages.length > 0 ? cards : null}
          <Text dimColor wrap="wrap">{[counts, legend].filter(Boolean).join(' · ')}</Text>
        </Box>
      </Box>
    )
    return (
      <Box flexDirection="column">
        <Text color="claude">Describe the task, then Enter on Create task.</Text>
        <Text> </Text>
        <Text bold>What</Text>
        <Box width={fieldWidth}>
          <Input
            key="what"
            autoFocus
            value={d.text}
            placeholder="Describe what to build, paste a GitHub issue URL or #123, or attach a brief file"
            submitLabel="to Name"
            onInput={typedWhat}
            onSubmit={text => void submitWhat(text)}
          />
        </Box>
        {d.hint === undefined ? null : <Text color="warning" wrap="wrap">{d.hint}</Text>}
        {d.isUiSuggested === true && !d.ui ? <Text dimColor wrap="wrap">Looks like it changes what people see: Has a UI (u, under Options) makes proof the change seen working.</Text> : null}
        <Text bold>Name</Text>
        <Box width={fieldWidth}>
          <Input
            key="name"
            value={d.title}
            placeholder="A short name for the task"
            submitLabel="to Create"
            onInput={title => edit(from => ({ ...from, title }))}
            onSubmit={() => void focus('create')}
          />
        </Box>
        <Text dimColor>{slugPath(d)}</Text>
        <Text> </Text>
        <Text bold>Workflow</Text>
        {flowRows}
        {stages.length === 0 ? (
          <Text dimColor>No fixed stages: every skill you run is recorded.</Text>
        ) : e.surface === 'terminal' ? null : (
          svgOf(stages)
        )}
        <Text> </Text>
        {/* Two sections fold into a line each of what they are set to, and one opens at a time: the form leads with what and how. */}
        {section('options', 'Options', 'o', optionsLine)}
        {d.openSection === 'options' ? (
          <Box flexWrap="wrap" columnGap={3}>
            <Button
              key="pr"
              label={`When done: ${FINISH_LABEL[d.finish]}`}
              hotkey="p"
              plain
              onPress={() => edit(from => ({ ...from, finish: nextFinish(from.finish) }))}
            />
            <Button
              key="worktree"
              label={`${d.worktree === 'now' ? '[x]' : '[ ]'} Work in its own git worktree`}
              hotkey="w"
              plain
              onPress={() => edit(from => ({ ...from, worktree: from.worktree === 'now' ? 'never' : 'now' }))}
            />
            <Button
              key="ui"
              label={`${d.ui ? '[x]' : '[ ]'} Has a UI: proof is the change seen working${d.isUiSuggested === true && !d.ui ? ' (suggested)' : ''}`}
              hotkey="u"
              plain
              onPress={() => edit(from => ({ ...from, ui: !from.ui }))}
            />
            <Button
              key="critic"
              label={`${d.critic ? '[x]' : '[ ]'} Review the build before it closes`}
              hotkey="l"
              plain
              onPress={() => edit(from => ({ ...from, critic: !from.critic }))}
            />
          </Box>
        ) : null}
        {section('models', 'Models', 'm', modelsLine)}
        {d.openSection === 'models' ? (
          <Box flexDirection="column">
            {hasPlanning ? (
              <Box flexWrap="wrap" columnGap={3}>
                <Select
                  key="planModel"
                  label="Plan model"
                  value={d.planModel}
                  options={[{ value: '', label: 'Same as build' }, ...modelOptions.slice(1)]}
                  onSelect={planModel => edit(from => ({ ...from, planModel }))}
                />
                <Select
                  key="planEffort"
                  label="Plan effort"
                  value={d.planEffort}
                  options={[{ value: '', label: 'Same as build' }, ...effortOptions.slice(1)]}
                  onSelect={value => edit(from => ({ ...from, planEffort: effortOf(value) }))}
                />
              </Box>
            ) : null}
            <Box flexWrap="wrap" columnGap={3}>
              <Select key="model" label={hasPlanning ? 'Build model' : 'Model'} value={d.model} options={modelOptions} onSelect={model => edit(from => ({ ...from, model }))} />
              <Select key="effort" label={hasPlanning ? 'Build effort' : 'Effort'} value={d.effort} options={effortOptions} onSelect={value => edit(from => ({ ...from, effort: effortOf(value) }))} />
            </Box>
            <Select
              key="helpers"
              label="Helper agents"
              value={d.helpers}
              options={[{ value: '', label: 'Their own model' }, ...HELPERS.map(({ value, label }) => ({ value, label }))]}
              onSelect={value => edit(from => ({ ...from, helpers: helpersOf(value) }))}
            />
          </Box>
        ) : null}
        <Text> </Text>
        {/* One action: Esc and the close mark cancel, as the line under it says. */}
        <Box gap={1}>
          <Button key="create" label={keyed('c', 'Create task')} hotkey="c" variant="primary" onPress={() => void create()} />
        </Box>
        <Text dimColor>{why ?? 'Tab: next field · Enter: confirm · Esc: cancel'}</Text>
      </Box>
    )
  })
}

