// Catch me up, on the side: a background subagent runs the recall skill for
// the open task, and its brief lands in the Catch up pane, so the person's
// session neither runs the recall nor carries its transcript mining.
import type { On } from 'claude-code'

import type { FlowTask } from '../types'
import { clip } from './doc'

const recap = { plugin: 'flow', key: 'recap' } as const

export const RECAP = 'flow-recap'

/** What the main conversation reads in place of the subagent's finished-task notice. */
export const RECAP_NOTICE = 'flow: the catch-up ran on the side; its brief is in the Catch up pane (/flow recap). Nothing here needs doing.'

/** The side agent's task: the recall skill, scoped to the open task, answering with the brief alone. */
export const recapPrompt = (task: FlowTask | null, root: string) =>
  [
    'Run the `flow:recall` skill with the Skill tool, then reply with only the brief its output contract asks for: no preamble, no notes about how you searched.',
    `Workspace: ${root}. Window: the last 7 days.`,
    task === null
      ? 'Topic: whatever was worked on in this workspace.'
      : [
          `Topic: the task "${task.title}" (.scratch/${task.slug}/task.json), workflow ${task.flow}, phase ${task.phase}.`,
          ...(task.artifacts.length === 0 ? [] : [`Its artifacts so far: ${task.artifacts.map(one => one.pointer).join(', ')}.`]),
        ].join(' '),
    'Read only; change nothing, create no issues, push nothing.',
  ].join('\n')

/** Whether a main-conversation row is the engine's notice that the catch-up agent finished. */
export const isRecapNotice = (texts: readonly string[], agentId: string) => texts.some(text => text.includes(agentId))

export const registerRecap = (on: On) => {
  // The side agent's answer is its own turn.complete: keep it, open the pane, say it is there.
  // A matcher keeps it apart from the other turn.complete hooks; every reason, so a failed run is not left running.
  on('turn.complete', { reason: ['answer', 'error', 'aborted', 'refusal'] }, async ($, e, next) => {
    const done = await next(e)
    const now = (await $.state.get(recap)).value ?? null
    if (e.agentId === undefined || now === null || now.agentId !== e.agentId) {
      return done
    }
    const brief = e.answer.trim()
    const at = await $.clock.now()
    await $.state.set(recap, brief === '' ? { ...now, error: `it ended without a brief (${e.reason})`, at } : { ...now, brief, at })
    $.ui.toast(brief === '' ? 'flow: the catch-up ended without a brief.' : 'flow: catch-up ready, in the Catch up pane.')
    // Opened unasked: it seats where it docks and never takes the keys.
    await $.ui.open({ id: RECAP, title: 'Catch up' }).catch(() => undefined)

    return done
  })

  // The engine tells the main conversation a background agent finished; for this one that is noise, so it
  // becomes one line. Rewritten, never refused: a row the engine appends is kept either way.
  on('session.append', async ($, e, next) => {
    if (e.agentId !== undefined || e.message.role !== 'user' || !['delivery', 'attachment'].includes(e.door)) {
      return next(e)
    }
    const id = (await $.state.get(recap)).value?.agentId
    const texts = e.message.content.flatMap(block => (block.type === 'text' && typeof block.text === 'string' ? [block.text] : []))

    return id === undefined || !isRecapNotice(texts, id) ? next(e) : next({ ...e, message: { ...e.message, content: [{ type: 'text', text: RECAP_NOTICE }] } })
  })

  // /flow recap: the latest brief, or a new catch-up when there is none for the open task.
  on('command.run', { command: 'flow' }, async ($, e, next) => {
    const [, verb = '', rest = ''] = /^(\S*)\s*([\s\S]*)$/.exec(e.args.trim()) ?? []
    if (verb !== 'recap') {
      return next(e)
    }
    const open = await $.flow.task()
    const now = (await $.state.get(recap)).value ?? null
    const isCurrent = now !== null && now.slug === (open?.slug ?? '') && now.error === undefined
    if (isCurrent && rest.trim() !== 'new') {
      await $.ui.open({ id: RECAP, title: 'Catch up', focus: true })

      return { text: now.brief === undefined ? 'The catch-up is still running on the side.' : 'Opened the latest catch-up. /flow recap new starts another.' }
    }
    const started = await $.flow.recap()

    return { text: started.isStarted ? 'Catching up on the side; the brief opens in the Catch up pane.' : `The catch-up did not start: ${started.reason ?? 'no reason given'}.` }
  })

  on('ui.render', { component: 'Pane', requestId: RECAP }, async ($, e) => {
    const { Box, Button, Markdown, Text } = $.ui.resolve(e)
    const now = (await $.state.get(recap)).value ?? null
    const again = <Button key="again" label="Catch up again" onPress={() => void $.flow.recap()} />
    if (now === null) {
      return (
        <Box flexDirection="column">
          <Text dimColor>No catch-up yet. It runs on the side and the brief lands here.</Text>
          {again}
        </Box>
      )
    }
    if (now.error !== undefined) {
      return (
        <Box flexDirection="column">
          <Text color="warning" wrap="wrap">{`The catch-up did not finish: ${now.error}`}</Text>
          {again}
        </Box>
      )
    }
    if (now.brief === undefined) {
      return <Text dimColor>Catching up on the side. The brief lands here; keep working meanwhile.</Text>
    }
    const body = clip(now.brief)

    return (
      <Box flexDirection="column">
        <Markdown key="brief" text={body.head} />
        {body.rest > 0 && <Text dimColor>{`${body.rest} more characters not shown`}</Text>}
        <Box columnGap={1} marginTop={1}>
          {again}
          <Button key="close" label="Close" role="dismiss" onPress={() => $.ui.close({ id: RECAP })} />
        </Box>
      </Box>
    )
  })
}

