// Seeing and steering the flow by hand: /flow why says what the task's state is made of and why it
// holds; /flow skip moves past a stage a person decides not to run. Pure; register.tsx serves both.
import type { FlowEvent, FlowStatus, FlowTask } from '../types'
import { GATED, capLog, gateArtifact, isWaived, nextAction, statusOf } from './flow'
import { FLOWS, STATUS_LABEL, stageLabel } from './flows'
import { judgedGap, proofGap, stuckReason } from './proof'
import { commandLine, holdNote, runsOn } from './status'
import { timeline } from './trail'

/** Everything the band's status is derived from, in lines a person or the model can read. */
export const explain = (task: FlowTask, busy: boolean) => {
  const status = statusOf(task, busy)
  const step = nextAction(task)
  const gate = gateArtifact(task)
  const lines = timeline(task)
  // The latest waiver of each block in this phase: a run of edit waivers is one line.
  const waivers = (['gate', 'edit', 'proof'] as const).flatMap(block => task.log.filter(one => one.kind === 'waived' && one.block === block && one.phase === task.phase).slice(-1))

  return [
    `${task.title} (.scratch/${task.slug}/task.json)`,
    `Workflow ${FLOWS[task.flow].label}, phase ${task.phase === 'new' ? 'not started' : `${stageLabel(task.phase)} (${task.phase})`}: ${STATUS_LABEL[status]}.`,
    `Why: ${holdNote(task, status) ?? step.why}.`,
    `Next: ${commandLine(task)}`,
    ...(task.phase in GATED
      ? [`Gate: ${gate === undefined ? `no ${GATED[task.phase]} recorded yet` : `reads ${gate.pointer}${isWaived(task) ? ', waived by Jev' : ''}`}.`]
      : []),
    ...waivers.map(one => `Jev waived: ${one.detail?.replace(/^Jev: /, '')}.`),
    ...[proofGap(task), judgedGap(task), stuckReason(task)].flatMap((gap, at) => (gap === undefined ? [] : [`${['Proof', 'Jev', 'Stuck'][at]}: ${gap}.`])),
    `Runs on: ${runsOn(task) ?? 'the session model'}.${task.tracker === undefined ? '' : ` Tracker: ${task.tracker}.`}`,
    ...(task.closedAt === undefined ? [] : ['Closed. /flow switch <slug> reopens it.']),
    'Latest events, minutes from the start:',
    ...(lines.length === 0 ? ['(none yet)'] : lines.slice(-12)),
    'Steer it: /flow skip moves past a stage, /flow allow waives a hold, /flow use <workflow> changes the chain, /flow done closes the task.',
  ].join('\n')
}

const SKIPPED = 'skipped by the person'

/** The stage a skip would move past: the one under way, or the next one when the current stage is settled. */
const skipTarget = (task: FlowTask, status = statusOf(task, false)) =>
  task.flow === 'freeform' || task.closedAt !== undefined ? undefined : task.phase === 'new' || status === 'ready' ? nextAction(task).stage : task.phase

/** Whether a skip would move anything; `status` is the one the caller already has, when it has one. */
export const canSkip = (task: FlowTask, status?: FlowStatus) => skipTarget(task, status) !== undefined

/**
 * The task with a stage skipped: the one under way, or the next one when the current stage is
 * settled. It is recorded done (and approved, and its proof waived, where the stage asks for that),
 * each marked as skipped, so the retro sees it. Undefined when nothing is left to skip.
 */

export const skipStage = (task: FlowTask, at: number, reason = ''): FlowTask | undefined => {
  const target = skipTarget(task)
  if (target === undefined) {
    return undefined
  }
  const entered = target === task.phase ? task : { ...task, phase: target, history: [...task.history, { skill: target, at }] }
  const kinds: FlowEvent['kind'][] = [...(target in GATED ? ['approve' as const] : []), ...(proofGap(entered) === undefined ? [] : ['allow' as const]), 'done']

  const detail = reason.trim() === '' ? SKIPPED : `${SKIPPED}: ${reason.trim().slice(0, 200)}`

  return kinds.reduce((one, kind) => ({ ...one, log: capLog([...one.log, { kind, detail, phase: target, at }]) }), entered)
}

