}

export const stageLabel = (stage: string) => STAGE_LABEL[stage] ?? stage

/** Why each stage is the next one, as the band and the pane say it. */
export const WHY: Record<string, string> = {
  'grill-with-docs': 'sharpen the idea and settle the decisions first',
  implement: 'build it here, in this session',
  'to-spec': 'multi-session: spec it before any /clear. One session? /implement here',
  'to-tickets': 'split the spec into tracer-bullet tickets',
  'implement-spec': 'build the whole graph, or /clear and /implement one ticket at a time',
  pr: 'open the pull request, with the checks as evidence',
  push: 'push the build to the default branch, once you say yes',
  retro: 'look back before you /clear; more tickets? /implement next',
  'diagnosing-bugs': 'reproduce it first, then fix it with a regression test',
  'improve-codebase-architecture': 'scan for deepening opportunities, then grill through the one you pick',
  wayfinder: 'name the destination and chart the decisions ahead',
  'wayfinder-clear': 'clear the map: one frontier ticket per session, /clear between',
}

/** The plugin whose skills the stages are; a `flow:<stage>` alias only points at one of them. */
export const UPSTREAM = 'mattpocock-skills'

const bare = (name: string) => name.slice(name.lastIndexOf(':') + 1)

/** Stages whose skill is flow's own, not an alias of an upstream one: `flow:push` is the only one that runs it. */
const OWN: readonly string[] = ['push']

/**
 * The listed command a stage or typed name runs: the exact name, else the upstream skill, else any
 * other plugin's, and never flow's own alias, which cannot launch a skill only a person may run.
 */
export const resolveCommand = (listed: readonly { name: string }[], command: string) =>
  (OWN.includes(bare(command)) ? listed.find(one => one.name === `flow:${bare(command)}`)?.name : undefined) ??
  listed.find(one => one.name === command && !one.name.startsWith('flow:'))?.name ??
  listed.find(one => one.name === `${UPSTREAM}:${bare(command)}`)?.name ??
  listed.find(one => bare(one.name) === bare(command) && !one.name.startsWith('flow:'))?.name

/**
 * The skill that runs a stage in place of mattpocock-skills' own: set only when the name came from
 * the bare-name fallback, so another plugin's skill of the same name answers, and undefined for the exact name, the upstream one or none.
 */
export const standIn = (listed: readonly { name: string }[], command: string) => {
  const found = resolveCommand(listed, command)

  return found === undefined || found === command || found === `${UPSTREAM}:${bare(command)}` || found === `flow:${bare(command)}` ? undefined : found
}

/** What a person is told when a stage ran another plugin's skill: once per command, so a narrow toast keeps the fix. */
export const standInRunNotice = (command: string, found: string) =>
  `flow: /${command} ran /${found} from another plugin, not ${UPSTREAM}. Install ${UPSTREAM}@flow-stack for the stage flow is built on.`

/** What a person is told when a new task's stages resolve to other plugins' skills, in one line. */
export const standInNotice = (found: readonly { command: string; name: string }[]) =>
  `flow: ${found.map(one => `/${one.command} resolves to ${one.name}`).join(', ')}, not ${UPSTREAM}.`

/** What a person is told when a workflow runs skills that are not installed: short, so a narrow toast keeps the fix. */
export const missingNotice = (missing: readonly string[]) =>
  `flow: missing ${missing.map(one => `/${one}`).join(', ')}. Install mattpocock-skills@flow-stack.`

