// Jev, TypeSafe's System One model: typed questions about a little state,
// typed answers and probabilities back. Facts stay in code (the proof gate,
// the workflow chain); Jev reads what only language carries: what the
// person's prompt says about earlier work, how far a turn's evidence goes, and
// whether a block is needed at all (a gate's document, an edit in planning, a
// build with no check to run). Pure: the questions, the thresholds and the
// policy as data, and the request and its parser. noun.ts sends it.
import type { FlowStatus, FlowTask, FlowWaiver, FlowWorkflow, JevAnswers, JevChoice, JevMode, JevNoul, JevQuestion, JevScore } from '../types'

import { FLOW_NAMES } from './flows'

export type JevConfig = { mode: JevMode; apiKey: string; baseUrl: string; model: string }

export const JEV_URL = 'https://api.typesafe.ai'
// Pinned: an alias moves, and the thresholds below were set against this version.
export const JEV_MODEL = 'jev-1.13.0'

export const noul = (instructions: string, criteria?: JevNoul['criteria']): JevNoul => ({
  type: 'noul',
  instructions,
  ...(criteria === undefined ? {} : { criteria }),
})
export const choice = <Option extends string>(instructions: string, criteria: Record<Option, string | null>): JevChoice<Option> => ({
  type: 'choice',
  instructions,
  criteria,
})
export const score = (instructions: string, criteria: readonly string[]): JevScore => ({ type: 'score', instructions, criteria })

/** What `$.http.fetch` takes for one request. */
export const request = (config: JevConfig, state: unknown, questions: Record<string, JevQuestion>) => ({
  url: `${config.baseUrl.replace(/\/+$/, '')}/v1/systemone`,
  init: {
    method: 'POST',
    headers: { authorization: `Bearer ${config.apiKey}`, 'content-type': 'application/json' },
    body: JSON.stringify({ model: config.model, state, questions }),
  },
})

const isRecord = (value: unknown): value is Record<string, unknown> => typeof value === 'object' && value !== null
const isShare = (value: unknown): value is number => typeof value === 'number' && value >= 0 && value <= 1

/** One answer narrowed to its question's type, or undefined when it is not that. */
const readOne = (question: JevQuestion, answer: unknown) => {
  if (!isRecord(answer)) {
    return undefined
  }
  if (question.type === 'noul') {
    return isShare(answer.noul) ? { noul: answer.noul } : undefined
  }
  if (!isShare(answer.confidence)) {
    return undefined
  }
  if (question.type === 'choice') {
    return typeof answer.choice === 'string' && Object.hasOwn(question.criteria, answer.choice)
      ? { choice: answer.choice, confidence: answer.confidence }
      : undefined
  }

  return typeof answer.score === 'number' ? { score: answer.score, confidence: answer.confidence } : undefined
}

/** The response body's answers, each narrowed to its question; undefined when any is missing or malformed. */
export const read = <Questions extends Record<string, JevQuestion>>(text: string, questions: Questions): JevAnswers<Questions> | undefined => {
  const body = (() => {
    try {
      return JSON.parse(text) as unknown
    } catch {
      return undefined
    }
  })()
  const answers = isRecord(body) && isRecord(body.answers) ? body.answers : undefined
  if (answers === undefined) {
    return undefined
  }
  const entries = Object.entries(questions).map(([id, question]) => [id, readOne(question, answers[id])] as const)

  // The mapped type over the questions is what each entry was narrowed to above.
  return entries.every(([, answer]) => answer !== undefined) ? (Object.fromEntries(entries) as JevAnswers<Questions>) : undefined
}

const clip = (text: string, length: number) => text.slice(0, length)
const tail = (text: string, length: number) => text.slice(-length)

// ---- The turn call: what the person's prompt says about the work so far.

export const TURN = {
  rework: noul(
    'Does `prompt` say that work the agent already did in this task is wrong, broken, incomplete or not what was asked for?',
    {
      true: 'It reports a defect in, or dissatisfaction with, output the agent already produced.',
      false: 'It asks for new work or a next step, answers a question, or approves, with no complaint about earlier output.',
    },
  ),
  kind: choice('What is `prompt` mainly doing?', {
    defect: 'Reports that something the agent built does not work: an error, a crash, a failing check, a pasted log, "still broken".',
    mismatch: 'Says the agent built something other than what was asked for: wrong place, wrong behaviour, off spec.',
    polish: 'Asks for a refinement of taste to work that functions: wording, spacing, colour, naming, "more options".',
    new_work: 'Asks for new work, a next step, a commit, a review or information, with no complaint about earlier output.',
    reply: 'Answers a question the agent asked, or is a bare go-ahead such as "yes", "continue" or "the second one".',
  }),
  lesson: noul(
    'Does `prompt` state a rule or preference about how the agent should work in general, beyond this one change?',
    {
      true: 'It says always, never, from now on, stop doing, or otherwise states a standing rule or habit the agent should keep.',
      false: 'It is only about this change.',
    },
  ),
} as const

export type TurnAnswers = JevAnswers<typeof TURN>

/** Prompts Jev never sees: a command, or a bare reply of a few words while a stage is under way. */
export const isJudgedPrompt = (text: string) => !text.trimStart().startsWith('/') && text.trim().split(/\s+/).length > 3

export const turnState = (input: { task: FlowTask; status: FlowStatus; lastAnswer: string; prompt: string }) => ({
  task: { title: input.task.title, phase: input.task.phase, status: input.status },
  last_answer: tail(input.lastAnswer, 1500),
  prompt: clip(input.prompt, 2000),
})

// ponytail: starting points from a small labelled set (evals/jev.eval.ts), not operating points
// measured on real prompts; tune them on the shadow log.
// `waive` and `prototype` lean hard towards keeping a block: a waiver needs Jev all but sure.
export const THRESHOLD = { rework: 0.8, lesson: 0.7, claim: 0.7, settled: 0.75, awaits: 0.5, confidence: 0.6, ui: 0.7, unclear: 0.2, gap: 0.4, waive: 0.15, prototype: 0.85 } as const

/** `lesson`: no complaint about this change, only a standing rule for the retro to encode. */
export type Rework = { kind: 'defect' | 'mismatch' | 'polish' | 'lesson'; isLesson: boolean; context?: string }

/** What a judged prompt means for the task: the rework it reports, if any, and what the model should read beside it. */
export const reworkOf = (answers: TurnAnswers): Rework | undefined => {
  const kind = answers.kind.choice
  // A refinement of taste is rework without being a complaint, so the choice alone carries it;
  // a defect or a mismatch also needs the prompt to read as one.
  const isLesson = answers.lesson.noul >= THRESHOLD.lesson
  if (kind !== 'defect' && kind !== 'mismatch' && kind !== 'polish') {
    return isLesson ? { kind: 'lesson', isLesson } : undefined
  }
  const isRework = kind === 'polish' ? answers.kind.confidence >= THRESHOLD.confidence : answers.rework.noul >= THRESHOLD.rework
  if (!isRework && !isLesson) {
    return undefined
  }
  const context =
    !isRework
      ? undefined
      : kind === 'defect'
      ? 'flow: this reads as a report that earlier work in this task failed. Reproduce it and find the root cause before changing code (Skill tool: diagnosing-bugs), fix it there, then run the checks again.'
      : kind === 'mismatch'
        ? 'flow: this reads as "not what was asked". Before changing code, restate what was asked against what was built, and say which part differs.'
        : undefined

  return { kind, isLesson, ...(context === undefined ? {} : { context }) }
}

// ---- The proof call: how far the turn's evidence goes.

export const EVIDENCE = [
  'Nothing in `ran` exercised the changed code: no command at all, or only reading files, git or installs.',
  'Static checks only: a typecheck, a lint or a build passed, and nothing ran the changed behaviour.',
  'Automated tests that plausibly cover the changed behaviour ran and passed.',
  'The real application, command or device was run and the changed behaviour was observed: a screenshot, a browser or emulator session, or the command output itself.',
] as const

export const PROOF = {
  claims_verified: noul('Does `final_message` say that tests, a build, a check or a manual run was carried out and passed?'),
  awaits_user: noul(
    'Does `final_message` end by asking the user a question, or for a decision, that must be answered before work continues?',
  ),
  evidence: score('How directly do the entries in `ran` show that the behaviour described in `task` works?', EVIDENCE),
} as const

export type ProofAnswers = JevAnswers<typeof PROOF>

/** One thing the turn ran: a Bash command or a tool, and whether it succeeded. */
export type Ran = { command: string; passed: boolean }

export const proofState = (input: { task: FlowTask; ticket: string; changed: readonly string[]; ran: readonly Ran[]; answer: string }) => ({
  task: clip(`${input.task.title}\n${input.ticket}`.trim(), 1500),
  changed_files: input.changed.slice(-20),
  ran: input.ran.slice(-30).map(one => ({ command: clip(one.command, 200), passed: one.passed })),
  final_message: tail(input.answer, 2000),
})

/** The evidence a task needs before it reads as proven: tests, or the change seen working when it has a UI. */
export const requiredEvidence = (task: FlowTask) => (task.ui === true ? 3 : 2)

const EVIDENCE_WORDS = ['nothing ran the changed code', 'only static checks ran', 'tests ran', 'the change was seen working'] as const

export type Judged = { ok: boolean; detail: string; isFalseClaim: boolean; isAwaiting: boolean }

/** What the proof answers mean for the task: whether the evidence is enough, in words, and what else the turn's end says. */
export const judgedOf = (answers: ProofAnswers, required: number): Judged => {
  const level = Math.max(0, Math.min(3, Math.round(answers.evidence.score)))
  // A spread distribution is no ground to withhold anything on.
  const isSure = answers.evidence.confidence >= THRESHOLD.confidence
  const isShort = isSure && level < required

  return {
    ok: !isShort,
    detail: isShort
      ? `${EVIDENCE_WORDS[level]}; ${required === 3 ? 'the change has not been seen working' : 'no test covers the change yet'}`
      : (EVIDENCE_WORDS[level] ?? ''),
    // The message says it was verified, and nothing that ran touched the change.
    isFalseClaim: isSure && level === 0 && answers.claims_verified.noul >= THRESHOLD.claim,
    isAwaiting: answers.awaits_user.noul >= THRESHOLD.awaits,
  }
}

// ---- The brief call: what the new-task dialog asks of the text in the What field.

export const BRIEF = {
  flow: choice('Which workflow suits the work `brief` describes?', {
    oneshot: 'A small, well-defined change or fix that needs no further decisions: the brief says enough to build it.',
    grill: 'A feature or change with a clear idea but a few open decisions, settled in conversation, then built in one session.',
    spec: 'A larger feature that needs a written spec and several tickets, built across sessions.',
    wayfind: 'A big, foggy goal with many unknowns, where a map of decisions must be charted before any spec.',
    architecture: 'Improving how existing code is structured with no new behaviour: refactor, uplift, deepen modules, reduce coupling, clean up a design.',
  }),
  ui: noul('Does the work `brief` describes change something a person sees or uses on a screen?', {
    true: 'It changes a screen of the product: a page, view, layout, component, style, or text the product shows its users.',
    false: 'It changes only code structure, data, tooling, services, documentation or behaviour with no visible surface in the product.',
  }),
  clear: noul('Is `brief` clear enough for someone to start work on it?', {
    true: 'It says what should change or be built, so a reader knows what done looks like.',
    false: 'It is a bare topic, a vague wish or a fragment, and leaves open what is to be done.',
  }),
  gap: choice('If `brief` is not clear enough to start, what is the most important thing it leaves out?', {
    none: 'Nothing important: it is clear enough to start.',
    goal: 'What outcome is wanted, or why.',
    place: 'Where in the product or code the change goes.',
    behaviour: 'What the result should do, or how it should behave.',
    scope: 'How much is wanted: where it starts and where it stops.',
  }),
} as const

export type BriefAnswers = JevAnswers<typeof BRIEF>

export const briefState = (text: string) => ({ brief: clip(text, 2000) })

/** What the dialog says to someone whose brief leaves a thing out, one short line per gap. */
const MISSING: Record<string, string> = {
  goal: 'Say what outcome you want.',
  place: 'Say where in the product or code it goes.',
  behaviour: 'Say what it should do.',
  scope: 'Say how much is wanted.',
}

export type BriefVerdict = { flow?: FlowWorkflow; isUi: boolean; hint?: string }

/** What the brief answers mean for the dialog: a workflow, only when Jev is sure of it, whether it has a UI, and what is missing when it is not clear. */
export const verdictOf = (answers: BriefAnswers): BriefVerdict => {
  const flow = FLOW_NAMES.find(name => name === answers.flow.choice)
  const isUnclear = answers.clear.noul < THRESHOLD.unclear
  const hint = isUnclear && answers.gap.confidence >= THRESHOLD.gap ? MISSING[answers.gap.choice] : undefined

  return {
    ...(flow === undefined || answers.flow.confidence < THRESHOLD.confidence ? {} : { flow }),
    isUi: answers.ui.noul >= THRESHOLD.ui,
    ...(hint === undefined ? {} : { hint }),
  }
}

// ---- The waiver calls: whether a block is needed. A block stays unless Jev is sure it is not:
// off, no key, a late or unreadable answer, or a doubtful one all keep it.

export type Waiver = FlowWaiver

export const GATE = {
  decision: noul('Does `document` leave open a decision a person must make or confirm before it is built?', {
    true: 'It names an open question, a product or design call, a trade-off it does not settle, or an irreversible choice (stored data, a public or shared interface, a deletion) a person should confirm.',
    false: 'Every choice it needs is made, and none is the kind a person must confirm first.',
  }),
  scope: noul('Does `document` go beyond what `brief` asks for, or leave out part of it?', {
    true: 'It adds work the brief did not ask for, or drops something the brief asked for.',
    false: 'It covers what the brief asks for and no more.',
  }),
  costly: noul('Would building the wrong thing from `document` be costly to undo?', {
    true: 'It touches stored data, a public or shared interface, security, money, or a large part of the codebase.',
    false: 'It is a contained change, cheap to redo if it turns out wrong.',
  }),
} as const

export type GateAnswers = JevAnswers<typeof GATE>

/**
 * What planning settled before the gate, as lines for its brief: each earlier planning stage's
 * report and the decisions it recorded, oldest first. A spec written after a grill is read against
 * what the grill decided, not the bare title.
 */
export const settledBefore = (task: FlowTask, planning: readonly string[]) =>
  task.log
    .filter(one => planning.includes(one.phase) && one.phase !== task.phase && (one.kind === 'decision' || one.kind === 'done') && one.detail !== undefined)
    .map(one => `${one.kind === 'decision' ? 'Decided' : 'Settled'} in ${one.phase}: ${one.detail}`)

/** What the gate question reads: the spec or the tickets, and what they were written from. */
export const gateState = (input: { task: FlowTask; what: string; brief: string; document: string }) => ({
  task: { title: input.task.title, phase: input.task.phase },
  document_kind: input.what,
  brief: clip(input.brief, 3000),
  document: clip(input.document, 6000),
})

/** A gate is waived only when Jev is sure of all three: no open decision, within the brief, cheap to redo. */
export const gateWaiverOf = (answers: GateAnswers): Waiver => {
  const held = [
    answers.decision.noul >= THRESHOLD.waive ? 'it may leave a decision open' : undefined,
    answers.scope.noul >= THRESHOLD.waive ? 'it may stray from the brief' : undefined,
    answers.costly.noul >= THRESHOLD.waive ? 'a wrong build may be costly to undo' : undefined,
  ].filter((one): one is string => one !== undefined)

  return held.length === 0
    ? { block: 'gate', isWaived: true, detail: 'no open decision, within the brief, cheap to redo' }
    : { block: 'gate', isWaived: false, detail: held.join('; ') }
}

export const EDIT = {
  prototype: noul(
    'Is the edit to `path` a throwaway prototype or spike that helps settle a decision in the planning phase `task.phase`, rather than building the planned change early?',
    {
      true: 'It sketches, measures or tries something out to choose between options: a prototype, a spike, an experiment, a scratch file.',
      false: 'It writes part of the real change before the plan is settled, or what it is for is unclear.',
    },
  ),
} as const

export type EditAnswers = JevAnswers<typeof EDIT>

export const editState = (input: { task: FlowTask; path: string; text: string; lastAnswer: string }) => ({
  task: { title: input.task.title, phase: input.task.phase },
  path: input.path,
  edit: clip(input.text, 1000),
  last_answer: tail(input.lastAnswer, 1500),
})

/** One edit in planning goes through only when Jev is sure it is a prototype. */
export const editWaiverOf = (answers: EditAnswers): Waiver =>
  answers.prototype.noul >= THRESHOLD.prototype
    ? { block: 'edit', isWaived: true, detail: 'a prototype to settle a decision' }
    : { block: 'edit', isWaived: false, detail: 'it may build ahead of the plan' }

/**
 * A build in a task that never ran a check: the PROOF answers stand in for one only when they say,
 * surely, that the change itself was run and seen working.
 */
export const noCheckWaiverOf = (answers: ProofAnswers): Waiver => {
  const level = Math.max(0, Math.min(3, Math.round(answers.evidence.score)))
  const isSeen = answers.evidence.confidence >= THRESHOLD.confidence && level === 3

  return isSeen
    ? { block: 'proof', isWaived: true, detail: 'no check to run, and the change was seen working' }
    : { block: 'proof', isWaived: false, detail: `no check ran, and ${EVIDENCE_WORDS[level]}` }
}

/** The shadow log's note for a waiver call: what Jev did, or in shadow what it would have done. */
export const waiverNote = (waiver: Waiver, mode: JevMode) =>
  `${waiver.isWaived ? (mode === 'on' ? 'waived' : 'would waive') : 'holds'}: ${waiver.detail}`

// ---- The ask call: questions the model puts to Jev through ask_jev, about facts it passes in.

export type Asked = { id: string; question: string; options?: readonly string[] }

/** The questions as Jev takes them: a choice when options are given, else a yes/no. Facts come from `state`, not from the wording. */
export const askQuestions = (asked: readonly Asked[]): Record<string, JevQuestion> =>
  Object.fromEntries(
    asked.map(one => {
      const instructions = `${one.question} Judge it only from the facts in \`state\`.`

      return [one.id, one.options === undefined ? noul(instructions) : choice(instructions, Object.fromEntries(one.options.map(option => [option, null])))]
    }),
  )

export type AskResult = { id: string; answer: string; probability: number; settled: boolean }

/** Each answer as the model reads it: yes/no or the option, how likely, and whether that clears the threshold. */
export const askResults = (questions: Record<string, JevQuestion>, answers: Record<string, unknown>): AskResult[] =>
  Object.keys(questions).map(id => {
    const one = answers[id] as { noul?: number; choice?: string; confidence?: number }
    const probability = Math.round((one.noul === undefined ? (one.confidence ?? 0) : Math.max(one.noul, 1 - one.noul)) * 100) / 100

    return { id, answer: one.noul === undefined ? (one.choice ?? '') : one.noul >= 0.5 ? 'yes' : 'no', probability, settled: probability >= THRESHOLD.settled }
  })

/** One decision as the shadow log keeps it. */
export type JevEntry = {
  at: number
  /** `gate`, `edit` and `noproof` judge whether a block is needed; `outcome` is what the person did at a gate Jev judged. */
  call: 'turn' | 'proof' | 'brief' | 'ask' | 'gate' | 'edit' | 'noproof' | 'outcome'
  ms: number
  slug: string
  phase: string
  answers: unknown
  note?: string
}

export const LOG_KEY = 'jev:log'
export const LOG_SIZE = 300

/** The log as stored, oldest first; anything else reads as empty. */
export const parseLog = (stored: unknown): JevEntry[] => (Array.isArray(stored) ? (stored as JevEntry[]) : [])

/** The stored log with one more decision, the oldest dropped past LOG_SIZE: what every call writes back. */
export const appended = (stored: unknown, entry: JevEntry) => [...parseLog(stored), entry].slice(-LOG_SIZE)

/** The latest decision about the task, as the board says it: `prompt: rework defect`, `turn end: short: only static checks ran`. */
export const lastDecision = (log: readonly JevEntry[], slug: string) => {
  const one = log.findLast(entry => entry.slug === slug)

  return one === undefined ? undefined : `${CALL_LABEL[one.call]}: ${one.note ?? 'no rework'}`
}

/** Each call as the board and `/flow jev` name it. */
const CALL_LABEL: Record<JevEntry['call'], string> = {
  turn: 'prompt',
  brief: 'brief',
  ask: 'asked',
  proof: 'turn end',
  gate: 'gate',
  edit: 'planning edit',
  noproof: 'no-check proof',
  outcome: 'gate outcome',
}

const isWaiveNote = (note: string | undefined) => note?.startsWith('waived') === true || note?.startsWith('would waive') === true

/**
 * What the person did at a gate Jev last judged for this task and phase, as the outcome entry's note,
 * or undefined when Jev never judged it: approved as it stood, or after the stage ran again or wrote
 * something new. The label that tunes the gate threshold: a gate approved as is did not need the read.
 */
export const gateOutcome = (log: readonly JevEntry[], task: FlowTask) => {
  const judged = log.findLast(one => one.call === 'gate' && one.slug === task.slug && one.phase === task.phase)
  if (judged === undefined) {
    return undefined
  }
  const isRevised =
    task.history.some(step => step.skill === task.phase && step.at > judged.at) ||
    task.artifacts.some(one => one.phase === task.phase && one.at > judged.at)

  return `${isRevised ? 'revised' : 'as is'}; Jev ${isWaiveNote(judged.note) ? 'would waive' : 'held'}`
}

/** The log in a few lines, for `/flow jev`: how often each call ran, how fast, and what the turn call found. */
export const logSummary = (log: readonly JevEntry[]) => {
  if (log.length === 0) {
    return 'No Jev decisions logged yet.'
  }
  const turns = log.filter(one => one.call === 'turn')
  const proofs = log.filter(one => one.call === 'proof')
  const median = [...log.map(one => one.ms)].sort((a, b) => a - b)[Math.floor(log.length / 2)] ?? 0
  const noted = (entries: readonly JevEntry[], note: string) => entries.filter(one => one.note?.startsWith(note) === true).length

  return [
    `${log.length} decisions, median ${median} ms.`,
    `Prompts judged: ${turns.length}; rework: ${noted(turns, 'rework')} (defect ${noted(turns, 'rework defect')}, mismatch ${noted(turns, 'rework mismatch')}, polish ${noted(turns, 'rework polish')}).`,
    `Turn ends judged: ${proofs.length}; evidence short: ${noted(proofs, 'short')}.`,
    `Asked by the model: ${log.filter(one => one.call === 'ask').length}.`,
    ...(['gate', 'edit', 'noproof'] as const).flatMap(call => {
      const judged = log.filter(one => one.call === call)

      return judged.length === 0 ? [] : [`${CALL_LABEL[call]} blocks judged: ${judged.length}; waived or would waive: ${judged.filter(one => isWaiveNote(one.note)).length}.`]
    }),
    ...(() => {
      const outcomes = log.filter(one => one.call === 'outcome' && one.note?.endsWith('would waive') === true)

      return outcomes.length === 0
        ? []
        : [`Gates Jev would waive that a person approved: ${outcomes.length}; as is ${noted(outcomes, 'as is')}, after a revision ${noted(outcomes, 'revised')}.`]
    })(),
    ...log.slice(-8).map(one => `  ${one.call} ${one.phase} ${one.ms}ms ${one.note ?? 'ok'}`),
  ].join('\n')
}

