// Whether a task's work already reached the default branch, so the pr or push stage has nothing to do,
// and what a retro's follow-up is called. Both read git or a retro file; neither moves the task.
import type { FlowFinish } from '../types'

type Ran = { exitCode: number; stdout: string; stderr: string }
export type Run = (argv: readonly string[]) => Promise<Ran | undefined>

/** The default branch: origin's HEAD, else a local `main`, else a local `master`, else `main`. Shared by close and landed. */
export const defaultBranch = async (run: Run) => {
  const head = (await run(['git', 'symbolic-ref', '--short', 'refs/remotes/origin/HEAD']))?.stdout.trim().replace(/^origin\//, '') ?? ''
  if (head !== '') {
    return head
  }
  const has = async (name: string) => (await run(['git', 'rev-parse', '--verify', '--quiet', `refs/heads/${name}`]))?.exitCode === 0

  return (await has('main')) ? 'main' : (await has('master')) ? 'master' : 'main'
}

/**
 * `done`: the stage steps aside, recorded done, saying why. `stop`: the stage cannot do its work and
 * should not run. Undefined: the stage runs as usual, also whenever git cannot tell.
 */
export const landed = async (run: Run, stage: Exclude<FlowFinish, 'none'>): Promise<{ done: string } | { stop: string } | undefined> => {
  const git = (...args: string[]) => run(['git', ...args])
  const branch = (await git('branch', '--show-current'))?.stdout.trim() ?? ''
  // Work still in the working tree has landed nowhere, whatever the commits say. flow's own .scratch
  // (a symlink in a worktree, which a `.scratch/` ignore rule misses) is not the task's work.
  const status = await git('status', '--porcelain', '--', '.', ':!.scratch')
  if (branch === '' || status?.exitCode !== 0 || status.stdout.trim() !== '') {
    return undefined
  }
  const base = await defaultBranch(run)
  const isFetched = (await git('fetch', '--quiet', 'origin', base))?.exitCode === 0
  const target = isFetched ? `origin/${base}` : base
  if (branch === base) {
    // ponytail: offline on the base branch, local main against itself says nothing, so the stage runs.
    const counted = isFetched ? await git('rev-list', '--count', `${target}..HEAD`) : undefined
    // Number('') is 0: only a count git printed counts.
    const ahead = counted?.exitCode === 0 && /^\d+$/.test(counted.stdout.trim()) ? Number(counted.stdout.trim()) : Number.NaN
    if (ahead === 0) {
      return { done: `${target} already has every commit on ${base}` }
    }

    return Number.isInteger(ahead) && ahead > 0 && stage === 'pr'
      ? { stop: `there ${ahead === 1 ? 'is 1 commit' : `are ${ahead} commits`} on ${base} and no branch to open a PR from: /push pushes them, or move them to a branch and run /pr again` }
      : undefined
  }
  if ((await git('merge-base', '--is-ancestor', branch, target))?.exitCode === 0) {
    return { done: `${branch} is already in ${target}${isFetched ? '' : ` (origin could not be fetched, so this is the local ${base})`}` }
  }
  // A squash merge leaves the branch's commits out of the base: the PR's own state says it landed, when
  // the head it merged is this one (a reused branch name has an older merged PR).
  const [pr, rev] = await Promise.all([run(['gh', 'pr', 'view', branch, '--json', 'state,headRefOid', '--jq', '.state+" "+.headRefOid']), git('rev-parse', 'HEAD')])
  const head = rev?.stdout.trim() ?? ''

  return pr?.exitCode === 0 && head !== '' && pr.stdout.trim() === `MERGED ${head}` ? { done: `the PR from ${branch} is already merged` } : undefined
}

const TITLE_MAX = 72

/** The text under a retro's `## <name>` heading, up to the next one; undefined when it has no such heading. */
const section = (text: string, name: string) => {
  const start = text.search(new RegExp(`^##\\s+${name}\\b.*$`, 'm'))
  if (start === -1) {
    return undefined
  }
  const rest = text.slice(start).split('\n').slice(1).join('\n')
  const end = rest.search(/^##\s/m)

  return end === -1 ? rest : rest.slice(0, end)
}

/**
 * A follow-up's name: its retro's first finding heading (no number, no trailing aside), then the first
 * Left undone lead, else its first line of prose. Never the parent's name, so chains do not nest.
 */
export const followUpTitle = (findings: string) => {
  // Under Findings when the retro has that section; any finding heading when it does not.
  const headings = [...(section(findings, 'Findings') ?? findings).matchAll(/^###[ \t]+(?:\d+\.[ \t]*)?(.*?)(?:[ \t]*\([^)\n]*\))?[ \t]*$/gm)].map(match => (match[1] ?? '').trim()).filter(one => one !== '')
  const leads = [...(section(findings, 'Left undone') ?? '').matchAll(/^\d+\.[ \t]+\*\*(.+?)\.?\*\*/gm)].map(match => (match[1] ?? '').trim()).filter(one => one !== '')
  // A retro's own title (`# Retro: <parent>`) is a heading, so the prose fallback never names the parent.
  // Markup (frontmatter, rules, tables, fences) is no name either.
  const prose = findings
    .replace(/^---\n[\s\S]*?\n---\n/, '')
    .split('\n')
    .map(line => line.replace(/^\s*(?:[-*]|\d+\.)\s+/, '').replace(/\*\*/g, '').trim())
    .find(line => /^[\p{L}\p{N}`"']/u.test(line))
  const [first = 'Follow-up', ...rest] = headings.length > 0 ? headings : leads.length > 0 ? leads : [(prose ?? 'Follow-up').replace(/\.$/, '')]
  const more = rest.length === 0 ? '' : ` and ${rest.length} more`

  return `${first.slice(0, TITLE_MAX - more.length).trim()}${more}`
}

