// Ponytail as an option: the plugin's own hooks switch it on for a whole session;
// this names a level for the build stages only, so the other stages stay unchanged.
export const PONYTAIL_LEVELS = ['lite', 'full', 'ultra'] as const
export type PonytailLevel = (typeof PONYTAIL_LEVELS)[number]

export const isPonytail = (value: unknown): value is PonytailLevel => PONYTAIL_LEVELS.some(level => level === value)

/** A line for a build stage's prompt, or nothing when the option is off or the stage does not write code. */
export const ponytailNote = (level: unknown, stage: string, builds: readonly string[]) =>
  isPonytail(level) && builds.includes(stage)
    ? `\n\nRun this stage under the ponytail skill at level ${level}: climb its ladder before writing code, and keep the shortest change that works.`
    : ''

