// $.flow: every read and write of the task goes through this noun, so other
// plugins can read the task and hook `flow.enter` or `flow.save`.
import type { On, Timer } from 'claude-code'

import type { FlowCreate, FlowEvent, FlowTask, FlowWaive, FlowWaiver, JevAnswers, JevQuestion } from '../types'
import {
  GATED,
  PLANNING,
  allowPhase,
  approvePhase,
  createTask,
  gateArtifact,
  isApproved,
  isIssue,
  isPassed,
  nextAction,
  retroFindings,
  recordArtifact,
  recordEvent,
  recordSkill,
  stageInput,
  statusOf,
  withDefaults,
} from './flow'
import { boardDoc, boardId, boardVersion, repoName } from './board'
import {
  EDIT,
  GATE,
  LOG_KEY,
  PROOF,
  appended,
  editState,
  editWaiverOf,
  gateOutcome,
  gateState,
  gateWaiverOf,
  noCheckWaiverOf,
  settledBefore,
  parseLog,
  proofState,
  read,
  request,
  waiverNote,
} from './jev'
import type { JevEntry } from './jev'
import { evidenceOf } from './judge'
import { defaultBranch, followUpTitle } from './landed'
import { missingNotice, resolveCommand, standIn, standInRunNotice } from './flows'
import { issueText, viewArgv } from './issue'
import type { JevConfig } from './jev'
import { isUnchecked, needsEditStamp, proofGap } from './proof'
import { RAIL_OPEN, ghostOf, holdNote } from './status'
import { ciOutcome } from './trail'
import { recapPrompt } from './recap'
import { skipStage } from './debug'

const current = { plugin: 'flow', key: 'task' } as const
const busy = { plugin: 'flow', key: 'busy' } as const
const recapRef = { plugin: 'flow', key: 'recap' } as const
const shownDoc = { plugin: 'flow', key: 'doc' } as const
const issue = { plugin: 'flow', key: 'issue' } as const
const boardView = { plugin: 'flow', key: 'boardView' } as const

const reason = (error: unknown) => (error instanceof Error ? error.message : String(error))
const taskPath = (root: string, slug: string) => `${root}/.scratch/${slug}/task.json`
const pointerKey = (root: string) => `current:${root}`
const openOnly = (task: FlowTask | null) => (task?.closedAt === undefined ? task : null)

// task.json read as a task, or why it is not one: a torn file costs that task only.
const readTask = (text: string): { task: FlowTask } | { why: string } => {
  try {
    const parsed: unknown = JSON.parse(text)
    if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
      return { why: 'it is not a task object' }
    }
    const missing = ['slug', 'title', 'entry', 'phase'].filter(key => typeof (parsed as Record<string, unknown>)[key] !== 'string')

    return missing.length > 0 ? { why: `it has no ${missing.join(', ')}` } : { task: withDefaults(parsed as FlowTask) }
  } catch {
    return { why: 'it is not valid JSON' }
  }
}

const BOARD_KEY = 'board'
// Changes within this window reach the board as one write.
const BOARD_SYNC_MS = 3_000

// Body rows the board asks for inline above the prompt.
const BOARD_ROWS = 24

// An edit waits on Jev mid-turn, so its answer gets no longer than a prompt's.
const EDIT_TIMEOUT_MS = 800

const CI_POLL_MS = 60_000
// Right after `gh pr create` a PR has no checks yet: wait this many polls for some.
const CI_EMPTY_POLLS = 5

export const registerNoun = (on: On, jev: JevConfig) => {
  // Task files already reported unreadable this load: each is toasted once.
  // ponytail: module state, lost on a reload, which toasts a bad file once more at worst.
  let skipped: readonly string[] = []
  // Commands already reported as run by another plugin's skill this load: each is toasted once.
  // ponytail: module state, lost on a reload, which says it once more at worst.
  let stoodIn: readonly string[] = []

  // Changes run one at a time: two hooks at once (a tool the model runs in parallel with another)
  // would each read the same task, and the later save would drop the earlier change. It lives
  // here, not in engine.create, which builds a fresh $ for each dispatch.
  // ponytail: one queue per plugin load, in this process; a lock file if two processes ever share a task.
  let queue: Promise<unknown> = Promise.resolve()

  on('engine.create', async (_, e, next) => {
    const built = await next(e)
    // ponytail: one CI watch at a time, the latest PR; a map by URL if tasks ever run PRs side by side.
    let watching: Timer | undefined
    // Tasks saved since the last board write, by slug.
    let unsent: Record<string, FlowTask> = {}
    let sending: Timer | undefined

    // Tasks live in the main working tree: inside a worktree `session.root()` moves, the repo's root does not.
    const home = async () => (await built.session.repo().catch(() => null))?.root ?? (await built.session.root())

    const task = async () => (await built.state.get(current)).value ?? null

    const load = async ({ slug }: { slug: string }) => {
      const root = await home()
      const text = await built.fs.read(taskPath(root, slug)).catch(() => undefined)

      if (typeof text !== 'string') {
        return null
      }
      const read = readTask(text)
      if ('task' in read) {
        return read.task
      }
      if (!skipped.includes(slug)) {
        skipped = [...skipped, slug]
        built.ui.toast(`flow skipped .scratch/${slug}/task.json: ${read.why}.`)
      }

      return null
    }

    const save = async (saved: FlowTask) => {
      const root = await home()
      // ponytail: $.fs has no rename or atomic write, so a crash mid-write can still leave a torn file; load skips it.
      await built.fs.write(taskPath(root, saved.slug), `${JSON.stringify(saved, null, 2)}\n`)
      if (saved.closedAt === undefined) {
        await built.store.set(pointerKey(root), saved.slug)
      } else {
        await built.store.delete(pointerKey(root))
      }
      // Another task opening disarms a Close pressed once on the last one.
      if ((await built.state.get(current)).value?.slug !== saved.slug) {
        await built.state.set(boardView, { isWhyOpen: false })
      }
      await built.state.set(current, openOnly(saved))
      if ((await board()) !== null) {
        unsent = { ...unsent, [saved.slug]: saved }
        sending?.cancel()
        sending = built.clock.after(BOARD_SYNC_MS, () => {
          const tasks = Object.values(unsent)
          unsent = {}
          // From a timer, so a rejection would vanish.
          void sync({ tasks }).catch((error: unknown) => built.ui.toast(`flow could not update the board: ${reason(error)}`))
        })
      }
    }

    const board = async () => {
      const url = await built.store.get(BOARD_KEY)

      return typeof url === 'string' ? url : null
    }

    const sync = async ({ tasks }: { tasks?: FlowTask[] } = {}) => {
      const url = await board()
      const open = await task()
      const sent = tasks ?? (open === null ? [] : [open])
      if (url === null || sent.length === 0) {
        return 0
      }
      const repo = repoName(await home())
      const at = await built.clock.now()
      // A write over an existing document must name the version it replaces.
      const versionOf = async (doc_id: string) => {
        const got = await built.tool.call({ tool: 'ArtifactData', action: 'get', url, collection: 'tasks', doc_id })

        return got.deny === undefined ? boardVersion(got.text ?? '') : undefined
      }
      const writes = await Promise.all(
        sent.slice(0, 50).map(async one => {
          const doc_id = boardId(repo, one.slug)
          const version = await versionOf(doc_id)

          return {
            op: 'set' as const,
            collection: 'tasks',
            doc_id,
            data: boardDoc(one, repo, at),
            ...(version === undefined ? {} : { if_version: version }),
          }
        }),
      )
      const ran = await built.tool.call({ tool: 'ArtifactData', action: 'batch', url, writes })
      if (ran.deny !== undefined || ran.isError === true) {
        built.ui.toast(`flow could not update the board: ${ran.deny ?? ran.text ?? 'no reason given'}`)

        return 0
      }

      return writes.length
    }

    const change = (move: (open: FlowTask, at: number) => FlowTask) => {
      const run = queue.then(async () => {
        // The file, not the state: a dispatch that began before the last save may still read the state it began with.
        const cached = await task()
        const open = cached === null ? null : ((await load({ slug: cached.slug })) ?? cached)
        if (open === null) {
          return null
        }
        const moved = move(open, await built.clock.now())
        if (moved !== open) {
          await save(moved)
        }

        return moved
      })
      queue = run.catch(() => undefined)

      return run
    }

    // A task that works in its own worktree runs each stage there: enter it (its existing one,
    // else a new one named after the slug) unless the session already left the main tree, and
    // link the main tree's .scratch in. False when it could not.
    const enterWorktree = async (open: FlowTask) => {
      const main = await home()
      if ((await built.session.root()) !== main) {
        return true
      }
      const listed = await built.process.run(['git', 'worktree', 'list', '--porcelain'], { cwd: main }).catch(() => undefined)
      const path = (listed?.stdout ?? '')
        .split('\n')
        .map(line => (line.startsWith('worktree ') ? line.slice('worktree '.length) : ''))
        .find(one => one !== main && one.split('/').at(-1) === open.slug)
      const entered = await built.tool.call(
        path === undefined ? { tool: 'EnterWorktree', name: open.slug } : { tool: 'EnterWorktree', path },
      )
      if (entered.deny !== undefined || entered.isError === true) {
        built.ui.toast(`flow could not enter the task's worktree: ${entered.deny ?? entered.text ?? 'no reason given'}`)

        return false
      }
      const root = await built.session.root()
      if (root !== main && !(await built.fs.exists(`${root}/.scratch`))) {
        const linked = await built.process.run(['ln', '-s', `${main}/.scratch`, `${root}/.scratch`]).catch(() => undefined)
        if (linked?.exitCode !== 0) {
          built.ui.toast(`flow could not link .scratch into the worktree: ${linked?.stderr.trim() || 'ln did not run'}. The stage will not see the task files.`)
        }
        // A `.scratch/` ignore rule misses a symlink: excluded here, `git add -A` never commits it and status stays clean.
        // ponytail: the main checkout's .git folder; a repo whose main checkout is itself a worktree keeps the link visible.
        const exclude = `${main}/.git/info/exclude`
        const excluded = (await built.fs.read(exclude).catch(() => '')) ?? ''
        if (!excluded.split('\n').includes('.scratch')) {
          await built.fs.write(exclude, `${excluded}${excluded === '' || excluded.endsWith('\n') ? '' : '\n'}.scratch\n`).catch(() => undefined)
        }
      }

      return true
    }

    // Closing puts the repo back where the next task starts: the default branch, pulled, the merged branch gone.
    // Only when nothing would be lost: uncommitted work stays put, and the branch goes only once it is in the
    // default branch. Not `git branch -d`: that also takes a branch merged into its own upstream, a pushed one
    // whose PR is still open.
    const close = async (open: FlowTask) => {
      await save({ ...open, closedAt: await built.clock.now() })
      const root = await built.session.root()
      const git = (args: string[]) => built.process.run(['git', ...args], { cwd: root }).catch(() => undefined)
      const branch = (await git(['branch', '--show-current']))?.stdout.trim() ?? ''
      const base = await defaultBranch(argv => built.process.run(argv, { cwd: root }).catch(() => undefined))
      const closed = `Closed: ${open.title}`
      if (branch === '' || branch === base) {
        return closed
      }
      // flow's own .scratch link in an older worktree is not the task's work.
      const status = await git(['status', '--porcelain', '--', '.', ':!.scratch'])
      if (status === undefined || status.stdout.trim() !== '') {
        return `${closed}. Still on ${branch}: it has uncommitted changes, so flow left it. Commit or stash them, then git switch ${base} && git pull --ff-only.`
      }
      const switched = await git(['switch', base])
      if (switched?.exitCode !== 0) {
        return `${closed}. Still on ${branch}: git switch ${base} failed (${switched?.stderr.trim() || 'git did not run'}).`
      }
      const pulled = await git(['pull', '--ff-only'])
      const isInBase = (await git(['merge-base', '--is-ancestor', branch, base]))?.exitCode === 0
      const deleted = isInBase ? await git(['branch', '-D', branch]) : undefined

      return [
        `${closed}. Back on ${base}`,
        pulled?.exitCode === 0 ? ', pulled.' : ` (git pull --ff-only failed: ${pulled?.stderr.trim().split('\n')[0] || 'git did not run'}).`,
        deleted?.exitCode === 0
          ? ` Deleted ${branch}, which is in ${base}.`
          : ` Kept ${branch}: it is not in ${base} yet (a squash merge looks that way too); git branch -D ${branch} once its PR is merged.`,
      ].join('')
    }

    // The retro's loopback: this task closes, and its findings open the next one as a Oneshot ticket.
    const followUp = async (open: FlowTask) => {
      const pointer = retroFindings(open)
      const findings = pointer === undefined ? undefined : await built.fs.read(`${await home()}/${pointer}`).catch(() => undefined)
      if (findings === undefined || findings.trim() === '') {
        built.ui.toast(`flow: no retro findings to follow up${pointer === undefined ? '' : ` (${pointer} could not be read)`}.`)

        return null
      }
      const closed = await close(open)
      const ticket = `Follow-up to: ${open.title} (${open.slug})\n\n${findings}`
      const { task: fixes } = await create({ text: followUpTitle(findings), ticket, flow: 'oneshot' })
      built.ui.toast(`${closed}. Opened ${fixes.title}.`)
      const ghost = ghostOf(fixes, statusOf(fixes, false))
      if (ghost !== undefined) {
        await built.prompt.suggest({ text: ghost }).catch(() => undefined)
      }

      return fixes
    }

    const note = (event: Omit<FlowEvent, 'phase' | 'at'>) => change((open, at) => recordEvent(open, event, at))

    const create = async ({ text, ticket, ...options }: FlowCreate) => {
      const at = await built.clock.now()
      const made = createTask(text, at, options)
      // Only an open task of the same title resumes; a closed one, or another title cut to the same slug, stays as it is.
      const place = async (n: number): Promise<{ fresh: FlowTask; existing: FlowTask | null }> => {
        const fresh = n === 1 ? made : { ...made, slug: `${made.slug}-${n}` }
        const existing = await load({ slug: fresh.slug })
        // A file that exists but does not read is someone's torn task: keep it for them to repair, never overwrite it.
        const isTorn = existing === null && (await built.fs.exists(taskPath(await home(), fresh.slug)))

        return isTorn || (existing !== null && (existing.closedAt !== undefined || existing.title !== made.title)) ? place(n + 1) : { fresh, existing }
      }
      const { fresh, existing } = await place(1)
      const { closedAt: _closedAt, ...resumed } = existing ?? fresh
      // A ticket, or text that says more than the name it was cut to, is kept beside task.json while
      // the phase is still `new`, so nextAction hands it to the first stage.
      const body = (ticket ?? (text.trim() === made.title ? '' : text)).trim()
      const pointer = `.scratch/${fresh.slug}/ticket.md`
      if (existing === null && body !== '') {
        await built.fs.write(`${await home()}/${pointer}`, `${body}\n`)
      }
      const opened = existing === null && body !== '' ? recordArtifact(resumed, pointer, at) : resumed
      await save(opened)

      return { task: opened, isNew: existing === null }
    }

    // Fail-open by construction: off, no key, late, refused or unreadable all read as null.
    const judge = async <Questions extends Record<string, JevQuestion>>({
      state,
      questions,
      timeoutMs = 2_000,
    }: {
      state: unknown
      questions: Questions
      timeoutMs?: number
    }): Promise<JevAnswers<Questions> | null> => {
      if (jev.mode === 'off') {
        return null
      }
      try {
        const apiKey = jev.apiKey !== '' ? jev.apiKey : ((await built.env.get('TYPESAFE_API_KEY')) ?? '')
        if (apiKey === '') {
          return null
        }
        const { url, init } = request({ ...jev, apiKey }, state, questions)
        // fetch has no timeout of its own, so it races the clock.
        const answered = await Promise.race([built.http.fetch(url, init), built.clock.sleep(timeoutMs).then(() => undefined)])

        return answered?.ok === true ? (read(answered.text, questions) ?? null) : null
      } catch {
        return null
      }
    }

    /** Appends one decision to Jev's shadow log; a store that refuses loses it, never the turn. */
    const logJev = async (entry: JevEntry) => {
      await built.store.set(LOG_KEY, appended(await built.store.get(LOG_KEY), entry)).catch(() => undefined)
    }

    /** An artifact's text: a file under the repo, or an issue through the tracker's CLI; undefined when it cannot be read. */
    const artifactText = async (pointer: string) => {
      if (pointer.startsWith('http')) {
        const ran = await built.process.run(viewArgv(pointer)).catch(() => undefined)

        return ran?.exitCode === 0 ? issueText(ran.stdout) : undefined
      }

      return built.fs.read(`${await home()}/${pointer}`).catch(() => undefined)
    }

    /** The question a block asks Jev, answered: which call it was, the answers, what they mean, and what it was about. Undefined when there is nothing to ask or no answer. */
    const judgeBlock = async (open: FlowTask, input: FlowWaive) => {
      if (input.block === 'edit') {
        if (!PLANNING.includes(open.phase)) {
          return undefined
        }
        const { lastAnswer } = evidenceOf(open.slug)
        const answers = await judge({ state: editState({ task: open, path: input.path, text: input.text, lastAnswer }), questions: EDIT, timeoutMs: EDIT_TIMEOUT_MS })

        return answers === null ? undefined : { call: 'edit' as const, answers, waiver: editWaiverOf(answers), subject: input.path }
      }
      if (input.block === 'proof') {
        if (!isUnchecked(open)) {
          return undefined
        }
        // Asked mid-turn from stage_done: the report stands in for the turn's last message.
        const seen = evidenceOf(open.slug)
        const answer = [seen.lastAnswer, input.summary].filter(Boolean).join('\n')
        const answers = await judge({ state: proofState({ task: open, ticket: '', changed: seen.changed, ran: seen.ran, answer }), questions: PROOF })

        return answers === null ? undefined : { call: 'noproof' as const, answers, waiver: noCheckWaiverOf(answers) }
      }
      const what = GATED[open.phase]
      const made = gateArtifact(open)
      if (what === undefined || made === undefined || isPassed(open)) {
        return undefined
      }
      const document = await artifactText(made.pointer)
      if (document === undefined || document.trim() === '') {
        return undefined
      }
      // The spec is read against what it was written from; the tickets against the spec.
      const spec = open.phase === 'to-tickets' ? open.artifacts.filter(one => one.phase === 'to-spec').at(-1)?.pointer : undefined
      const source = spec ?? open.artifacts.find(one => one.phase === 'new')?.pointer
      const written = (source === undefined ? undefined : await artifactText(source)) ?? open.title
      // A spec is read against what was decided before it, so a grill's decisions count as the brief.
      const brief = [written, ...settledBefore(open, PLANNING)].join('\n')
      const answers = await judge({ state: gateState({ task: open, what, brief, document }), questions: GATE })

      return answers === null ? undefined : { call: 'gate' as const, answers, waiver: gateWaiverOf(answers), subject: made.pointer }
    }

    // A block stays unless Jev answers, in `on`, that it is surely not needed.
    const waive = async (input: FlowWaive): Promise<FlowWaiver | null> => {
      const open = await task()
      if (jev.mode === 'off' || open === null) {
        return null
      }
      const started = await built.clock.now()
      const judged = await judgeBlock(open, input)
      if (judged === undefined) {
        return null
      }
      const about = judged.subject === undefined ? '' : ` (${judged.subject})`
      await logJev({
        at: started,
        call: judged.call,
        ms: (await built.clock.now()) - started,
        slug: open.slug,
        phase: open.phase,
        answers: judged.answers,
        note: `${waiverNote(judged.waiver, jev.mode)}${about}`,
      })
      if (jev.mode !== 'on' || !judged.waiver.isWaived) {
        return null
      }
      const detail = `Jev: ${judged.waiver.detail}${about}`
      await note({ kind: 'waived', block: judged.waiver.block, detail })

      return { ...judged.waiver, detail }
    }

    // A person's approval of a gate Jev judged is the label that tunes the waiver: logged in shadow and on alike.
    const approve = async () => {
      const before = await task()
      const moved = await change(approvePhase)
      const outcome = moved === null || before === null || isApproved(before) || jev.mode === 'off' ? undefined : gateOutcome(parseLog(await built.store.get(LOG_KEY)), moved)
      if (moved !== null && outcome !== undefined) {
        await logJev({ at: await built.clock.now(), call: 'outcome', ms: 0, slug: moved.slug, phase: moved.phase, answers: null, note: outcome })
      }

      return moved
    }

    return {
      ...built,
      flow: {
        task,
        create,
        judge,
        load,
        save,
        note,
        board,
        sync,
        share: async ({ url }: { url: string | null }) => {
          if (url === null) {
            await built.store.delete(BOARD_KEY)
          } else {
            await built.store.set(BOARD_KEY, url)
          }
        },
        all: async () => {
          const root = await home()
          const dirs = await built.fs.list(`${root}/.scratch`).catch(() => [])
          const tasks = await Promise.all(dirs.filter(one => one.kind === 'dir').map(one => load({ slug: one.name })))

          return tasks.filter((one): one is FlowTask => one !== null).sort((a, b) => b.createdAt - a.createdAt)
        },
        next: async () => {
          const open = await task()

          return open === null ? null : nextAction(open)
        },
        suggest: async () => {
          const open = await task()
          const text = open === null ? undefined : ghostOf(open, statusOf(open, (await built.state.get(busy)).value ?? false))
          if (text !== undefined) {
            await built.prompt.suggest({ text }).catch(() => undefined)
          }
        },
        // Docked beside the transcript the board stays open when Esc hands the keys back; inline
        // above the prompt it behaves as a dialog, which Esc closes.
        show: async ({ docks }: { docks: boolean }) => {
          await built.ui.open(
            docks
              ? { ...RAIL_OPEN, focus: true }
              : { ...RAIL_OPEN, focus: true, closeOnEscape: true, holdToasts: true, rows: BOARD_ROWS },
          )
        },
        run: async (input?: { alt?: boolean; expect?: { slug: string; phase: string } }) => {
          const open = await task()
          const isMoved = input?.expect !== undefined && (open?.slug !== input.expect.slug || open.phase !== input.expect.phase)
          if (open === null || isMoved) {
            return
          }
          const recommended = nextAction(open)
          const step = input?.alt === true && recommended.alt !== undefined ? recommended.alt : recommended
          // A build leaves its stage on proof: the next stage waits for a passing check, or a person's /flow allow.
          if (proofGap(open) !== undefined) {
            built.ui.toast(`Not proven yet: ${holdNote(open, 'proof') ?? 'no check has passed'}. Run the checks, or Ship anyway on the band (/flow allow) to move on.`)

            return
          }
          // The mod's own verbs run here: a plugin's own $.command.run never reaches its own command hook.
          if (step.command === 'flow') {
            if (step.args === 'done') {
              built.ui.toast(await close(open))
            } else if (step.args === 'approve') {
              await approve()
            } else if (step.args === 'followup') {
              await followUp(open)
            }

            return
          }
          if (open.worktree === 'now' && !(await enterWorktree(open))) {
            return
          }
          const listed = await built.command.list().catch(() => [])
          const found = resolveCommand(listed, step.command)
          if (found === undefined) {
            built.ui.toast(missingNotice([step.command]))

            return
          }
          if (standIn(listed, step.command) !== undefined && !stoodIn.includes(step.command)) {
            stoodIn = [...stoodIn, step.command]
            built.ui.toast(standInRunNotice(step.command, found))
          }
          // Run from a timer, so a rejection would vanish: say it, and how to run the stage by hand.
          await built.command
            .run({ command: found, args: step.args ?? stageInput(open, step.command) ?? '' })
            .catch((error: unknown) => built.ui.toast(`flow: /${found} did not start (${reason(error)}). Type it in the prompt to run it.`))
        },
        enter: ({ skill }: { skill: string }) => change((open, at) => recordSkill(open, skill, at)),
        produce: ({ pointer }: { pointer: string }) => change((open, at) => recordArtifact(open, pointer, at)),
        // The doc tab draws an issue from state, fetched here because a render hook may not run a process or write state.
        // Beside the session, never in it: the recall mines transcripts and the shared record, which would crowd the person's context.
        recap: async () => {
          const open = await task()
          const slug = open?.slug ?? ''
          const now = (await built.state.get(recapRef)).value ?? null
          if (now !== null && now.agentId !== undefined && now.brief === undefined && now.error === undefined) {
            return { isStarted: false, reason: 'one is already running' }
          }
          const at = await built.clock.now()
          const started = await built.agent
            .spawn({ subagentType: 'general-purpose', description: 'Catch me up', prompt: recapPrompt(open, await home()) })
            .catch((error: unknown) => ({ deny: reason(error), agentId: undefined }))
          if (started.deny !== undefined || started.agentId === undefined) {
            const why = started.deny ?? 'no agent started'
            await built.state.set(recapRef, { slug, error: why, at })
            built.ui.toast(`flow: the catch-up did not start: ${why}`)

            return { isStarted: false, reason: why }
          }
          await built.state.set(recapRef, { slug, agentId: started.agentId, at })

          return { isStarted: true }
        },
        doc: async ({ pointer }: { pointer: string }) => {
          await built.state.set(shownDoc, pointer)
          if (!isIssue(pointer)) {
            return
          }
          const argv = viewArgv(pointer)
          const ran = await built.process.run(argv).then(
            done => done,
            (error: unknown) => ({ exitCode: -1, stdout: '', stderr: reason(error) }),
          )
          const text = ran.exitCode === 0 ? issueText(ran.stdout) : undefined
          const why = ran.stderr.trim().split('\n')[0] || `${argv[0]} did not print an issue`
          await built.state.set(issue, text === undefined ? { pointer, error: `${argv[0]} could not read it: ${why}` } : { pointer, text })
        },
        track: ({ tracker }: { tracker: 'github' | 'gitlab' }) => change(open => (open.tracker === tracker ? open : { ...open, tracker })),
        // Decided on the file, inside the queue: a check that ran beside the edit has landed by then.
        edited: ({ path }: { path: string }) =>
          change((open, at) => (needsEditStamp(open) ? recordEvent(open, { kind: 'edit', detail: path }, at) : open)),
        approve,
        waive,
        // A person's call: null when nothing is left to skip.
        // In the queue, so a CI note or an edit stamp landing beside it is not lost.
        skip: async (input?: { reason?: string }) => {
          let isSkipped = false
          const moved = await change((open, at) => {
            const skipped = skipStage(open, at, input?.reason)
            isSkipped = skipped !== undefined

            return skipped ?? open
          })

          return isSkipped ? moved : null
        },
        close: async () => {
          const open = await task()

          return open === null ? 'No open task.' : close(open)
        },
        followUp: async () => {
          const open = await task()

          return open === null ? null : followUp(open)
        },
        allow: (input?: { reason?: string }) => change((open, at) => allowPhase(open, at, input?.reason)),
        watch: async ({ url }: { url: string }) => {
          watching?.cancel()
          let polls = 0
          const poll = async () => {
            polls += 1
            const ran = await built.process.run(['gh', 'pr', 'checks', url, '--json', 'bucket']).catch(() => undefined)
            const outcome = ran === undefined ? undefined : ciOutcome(ran.stdout)
            if (outcome === 'pending' || (outcome === undefined && polls < CI_EMPTY_POLLS)) {
              return
            }
            watching?.cancel()
            watching = undefined
            if (outcome !== undefined) {
              await note({ kind: 'ci', detail: url, ok: outcome === 'pass' })
              built.ui.toast(`CI ${outcome === 'pass' ? 'passed' : 'failed'}: ${url}`)
            }
          }
          // From a timer, so a rejection would vanish.
          watching = built.clock.every(CI_POLL_MS, () => void poll().catch((error: unknown) => built.ui.toast(`flow could not check CI for ${url}: ${reason(error)}`)))
        },
        resume: async () => {
          const slug = await built.store.get(pointerKey(await home()))
          const open = openOnly(typeof slug === 'string' ? await load({ slug }) : null)
          await built.state.set(current, open)

          return open
        },
      },
    }
  })
}

