// What the settings pane lists and how a value is checked: the plugin's options
// (defaults for new tasks and the mod) and the open task's own values. Pure; the
// drawing and the saving live in settings.tsx.
import type { PluginOptions } from 'claude-code'

import type { FlowTask } from '../types'
import { FINISHES, FINISH_LABEL, isFlow, isHelpers, recordEvent } from './flow'
import { EFFORTS, FLOWS, FLOW_NAMES, MODELS } from './flows'
import { JEV_MODEL, JEV_URL } from './jev'

export type Choice = { value: string; label: string }

type Common = { name: string; label: string; help: string }
/** An option as the pane lists it: a toggle, one of a list, or text (`isNumber` for a whole number to check). */
export type Setting =
  | (Common & { kind: 'toggle'; fallback: boolean })
  | (Common & { kind: 'pick'; fallback: string; choices: readonly Choice[] })
  | (Common & { kind: 'text'; fallback: string; isNumber?: true })

const models = (first: Choice): readonly Choice[] => [first, ...MODELS.map(one => ({ value: one.alias, label: one.label }))]
const SESSION: Choice = { value: 'session', label: 'Session model' }

/** The manifest's options, in the order the pane lists them; the help is each description in a line. */
export const DEFAULTS: readonly Setting[] = [
  { name: 'autoAdvance', kind: 'toggle', fallback: false, label: 'Auto-advance', help: 'Run the next stage at once after an approval or a finished build.' },
  { name: 'clearAt', kind: 'text', isNumber: true, fallback: '50', label: 'Clear nudge %', help: 'Suggest /clear from this share of the context (1 to 100).' },
  { name: 'checks', kind: 'text', fallback: '', label: 'Extra checks', help: 'Commands that count as checks, comma-separated.' },
  { name: 'planModel', kind: 'pick', fallback: 'session', choices: models(SESSION), label: 'Plan model', help: 'What new tasks plan on; session keeps the build model.' },
  { name: 'buildModel', kind: 'pick', fallback: 'session', choices: models(SESSION), label: 'Build model', help: 'What new tasks build on; session keeps the session model.' },
  {
    name: 'helpers',
    kind: 'pick',
    fallback: 'own',
    choices: [{ value: 'own', label: 'Their own' }, { value: 'stage', label: 'Follow stage' }, ...models(SESSION).slice(1)],
    label: 'Helper agents',
    help: 'What Explore, general-purpose and Plan run on.',
  },
  { name: 'critic', kind: 'toggle', fallback: false, label: 'Second look', help: 'A fork reviews a new task’s build before it closes.' },
  {
    name: 'criticPanel',
    kind: 'pick',
    fallback: 'off',
    choices: [{ value: 'off', label: 'Fork alone' }, ...MODELS.map(one => ({ value: one.alias, label: one.label }))],
    label: 'Second model',
    help: 'Also review the diff on this model; only a finding both raise holds.',
  },
  { name: 'rules', kind: 'text', fallback: '', label: 'House rules file', help: 'A file added to every stage skill of a new task.' },
  {
    name: 'ponytail',
    kind: 'pick',
    fallback: 'off',
    choices: ['off', 'lite', 'full', 'ultra'].map(value => ({ value, label: value })),
    label: 'Ponytail',
    help: 'How hard builds push for the smallest change.',
  },
  {
    name: 'jevMode',
    kind: 'pick',
    fallback: 'off',
    choices: ['off', 'shadow', 'on'].map(value => ({ value, label: value })),
    label: 'Jev',
    help: 'off never calls it; shadow only logs; on also acts.',
  },
  { name: 'jevBaseUrl', kind: 'text', fallback: JEV_URL, label: 'Jev base URL', help: 'Where /v1/systemone is served.' },
  { name: 'jevModel', kind: 'text', fallback: JEV_MODEL, label: 'Jev model', help: 'Pinned: the thresholds were set against it.' },
]

/** What the option holds now, as text for a field or a pick; a toggle reads true or false. */
export const heldBy = (options: PluginOptions, setting: Setting): string | boolean => {
  const held = options[setting.name]
  if (setting.kind === 'toggle') {
    return typeof held === 'boolean' ? held : setting.fallback
  }

  return typeof held === 'string' || typeof held === 'number' ? String(held) : setting.fallback
}

/** The value `$.config.set` takes for text typed into a row, or why it is refused. */
export const parseText = (setting: Setting, text: string): { value: string | number } | { refusal: string } => {
  const one = text.trim()
  if (setting.kind !== 'text') {
    return { refusal: `${setting.label} is not a text field.` }
  }
  if (setting.isNumber) {
    const n = Number(one)

    return one !== '' && Number.isInteger(n) && n >= 1 && n <= 100 ? { value: n } : { refusal: `${setting.label} takes a whole number from 1 to 100.` }
  }
  if (setting.name === 'jevModel' && one === '') {
    return { refusal: 'Jev model cannot be empty.' }
  }
  if (setting.name === 'jevBaseUrl' && !/^https?:\/\/\S+$/.test(one)) {
    return { refusal: 'Jev base URL starts with http:// or https://.' }
  }

  return { value: one }
}

/** Whether a pick's value is one of its choices; the pane only offers those, a button or a hook may send another. */
export const isChoice = (setting: Setting, value: string) => setting.kind === 'pick' && setting.choices.some(one => one.value === value)

/**
 * The /config row a default is stored in, or why it cannot be written. The key is `flow.<name>` with
 * the install after `flow` (`flow@flow-stack`, `flow@inline` for --plugin-dir): only the row the
 * engine lists is stored where this install reads it back. No row is a session with no settings menu
 * (claude -p); a list that failed says so, rather than passing for one.
 */
export const configRow = (rows: readonly { key: string; isLocked: boolean }[] | Error, name: string): { key: string } | { refusal: string } => {
  if (rows instanceof Error) {
    return { refusal: `the settings could not be read (${rows.message})` }
  }
  const row = rows.find(one => new RegExp(`^flow(@[^.]+)?\\.${name}$`).test(one.key))

  return row === undefined ? { refusal: 'this session has no settings menu (claude -p); change it in an interactive session' } : row.isLocked ? { refusal: 'your organization sets it' } : { key: row.key }
}

/** configRow over the engine's own list, a failed list kept as the reason: what the pane and /flow jev both ask. */
export const configRowOf = async (list: () => Promise<readonly { key: string; isLocked: boolean }[]>, name: string) =>
  configRow(await list().catch((error: unknown) => (error instanceof Error ? error : new Error(String(error)))), name)

export const SESSION_DEFAULT: Choice = { value: '', label: 'Session default' }
export const SAME_AS_BUILD: Choice = { value: '', label: 'Same as build' }

/** Which of the task's own fields a row sets. */
export type TaskField = 'flow' | 'finish' | 'ui' | 'critic' | 'rules' | 'model' | 'effort' | 'planModel' | 'planEffort' | 'helpers'

export type TaskRow =
  | (Common & { field: TaskField; kind: 'toggle' })
  | (Common & { field: TaskField; kind: 'pick'; choices: readonly Choice[] })
  | (Common & { field: 'rules'; kind: 'text' })

const efforts = (first: Choice): readonly Choice[] => [first, ...EFFORTS.map(value => ({ value, label: value }))]

/** The open task's values, as the dialog and `/flow new` flags set them. The worktree is shown, not set: it is entered when the first stage runs. */
export const TASK_ROWS: readonly TaskRow[] = [
  { field: 'flow', kind: 'pick', name: 'flow', label: 'Workflow', help: 'The stages it follows, as /flow use.', choices: FLOW_NAMES.map(value => ({ value, label: FLOWS[value].label })) },
  { field: 'finish', kind: 'pick', name: 'finish', label: 'When done', help: 'Open a PR, push to main, or neither.', choices: FINISHES.map(value => ({ value, label: FINISH_LABEL[value] })) },
  { field: 'ui', kind: 'toggle', name: 'ui', label: 'Has a UI', help: 'Proof is the change seen working.' },
  { field: 'critic', kind: 'toggle', name: 'critic', label: 'Review before close', help: 'A fork names what the build likely missed.' },
  { field: 'rules', kind: 'text', name: 'rules', label: 'House rules file', help: 'Added to every stage skill; empty for none.' },
  { field: 'model', kind: 'pick', name: 'model', label: 'Build model', help: 'What the task’s turns run on.', choices: models(SESSION_DEFAULT) },
  { field: 'effort', kind: 'pick', name: 'effort', label: 'Build effort', help: 'The effort of those turns.', choices: efforts(SESSION_DEFAULT) },
  { field: 'planModel', kind: 'pick', name: 'planModel', label: 'Plan model', help: 'What the planning stages run on.', choices: models(SAME_AS_BUILD) },
  { field: 'planEffort', kind: 'pick', name: 'planEffort', label: 'Plan effort', help: 'The effort of the planning stages.', choices: efforts(SAME_AS_BUILD) },
  {
    field: 'helpers',
    kind: 'pick',
    name: 'helpers',
    label: 'Helper agents',
    help: 'What Explore, general-purpose and Plan run on.',
    choices: [{ value: '', label: 'Their own' }, { value: 'stage', label: 'Follow stage' }, ...MODELS.map(one => ({ value: one.alias, label: one.label }))],
  },
]

/** What a task row holds now, in the form its control takes. */
export const taskValue = (task: FlowTask, field: TaskField): string | boolean => {
  switch (field) {
    case 'ui':
    case 'critic':
      return task[field] === true
    default:
      return task[field] ?? ''
  }
}

/** The task with one field set (or cleared by `''`), or why that value is not one it takes. Changing the workflow is logged, as /flow use does. */
export const withField = (task: FlowTask, field: TaskField, value: string | boolean, at: number): FlowTask | string => {
  // A cleared field is undefined, which the task file leaves out when it is written.
  const rest: FlowTask = { ...task, [field]: undefined }
  const text = typeof value === 'string' ? value.trim() : ''
  switch (field) {
    case 'flow':
      return typeof value === 'string' && isFlow(value) ? (task.flow === value ? task : recordEvent({ ...task, flow: value }, { kind: 'flow', detail: value }, at)) : `${String(value)} is not a workflow.`
    case 'finish': {
      const finish = FINISHES.find(one => one === value)

      return finish === undefined ? `${String(value)} is not a way to finish.` : { ...task, finish }
    }
    case 'ui':
    case 'critic':
      return value === true ? { ...task, [field]: true } : rest
    case 'effort':
    case 'planEffort': {
      const effort = EFFORTS.find(one => one === text)

      return text === '' ? rest : effort === undefined ? `${text} is not an effort.` : { ...task, [field]: effort }
    }
    case 'model':
    case 'planModel':
      return text === '' ? rest : MODELS.some(one => one.alias === text) ? { ...task, [field]: text } : `${text} is not a model.`
    case 'helpers':
      return text === '' ? rest : isHelpers(text) ? { ...task, helpers: text } : `${text} is not a helpers route.`
    case 'rules':
      return text === '' ? rest : { ...task, rules: text }
  }
}

