// The settings pane: every flow setting seen and changed in one place, so nobody
// needs /config or flags. The open task's own values come first, then the
// plugin's options. /flow settings and the board's Settings button open it.
import type { On, PluginOptions } from 'claude-code'

import { RAIL_OPEN, fit } from './status'
import { DEFAULTS, TASK_ROWS, configRowOf, heldBy, isChoice, parseText, taskValue, withField } from './prefs'
import type { Choice, Setting, TaskRow } from './prefs'

// The validator lists state reads per file, so each file spells its reference.
const prefs = { plugin: 'flow', key: 'settings' } as const

export const SETTINGS = 'flow-settings'

/** How the pane opens: docked 60 columns wide, or inline as a dialog that takes the keys and closes on Esc. */
export const SETTINGS_OPEN = { id: SETTINGS, title: 'Settings', columns: 60, focus: true, closeOnEscape: true, rows: 26 } as const

type Row = Setting | TaskRow

export const registerSettings = (on: On, options: PluginOptions) => {
  on('command.run', { command: 'flow' }, async ($, e, next) => {
    if (e.args.trim() !== 'settings') {
      return next(e)
    }
    const opened = await $.ui.open(SETTINGS_OPEN)

    return { text: opened.isPlaced ? 'Settings opened.' : `Could not seat the settings pane: ${opened.reason}` }
  })

  on('ui.render', { component: 'Pane', requestId: SETTINGS }, async ($, e) => {
    const { Box, Button, Text } = $.ui.resolve(e)
    // The mobile app draws no field yet: a pick becomes a row of buttons, and text is read-only.
    const fields = e.surface === 'mobile' ? undefined : $.ui.resolve(e)
    const note = (await $.state.get(prefs)).value
    const open = await $.flow.task()
    const width = Math.max(20, e.props.bodyColumns - 2)
    const isInline = e.props.placement === 'inline'

    // The note stays in the pane for the next draw (and the next load); the toast is the moment's confirmation.
    const remember = (text: string, isBad: boolean, reopen: boolean) => $.state.set(prefs, { reopen, note: text, isBad })
    const say = async (text: string, isBad = false) => {
      $.ui.toast(text)
      await remember(text, isBad, false)
    }
    const shown = (row: Row, held: string | number | boolean) =>
      typeof held === 'boolean' ? (held ? 'on' : 'off') : row.kind === 'pick' ? (row.choices.find(one => one.value === held)?.label ?? String(held)) : held === '' ? 'none' : String(held)

    const changeTask = async (row: TaskRow, value: string | boolean) => {
      const task = await $.flow.task()
      if (task === null) {
        return say('No open task.', true)
      }
      const moved = withField(task, row.field, value, await $.clock.now())
      if (typeof moved === 'string') {
        return say(moved, true)
      }
      if (moved !== task) {
        await $.flow.save(moved)
      }

      return say(`Saved ${row.label}: ${shown(row, value)}.`)
    }

    const changeDefault = async (setting: Setting, value: string | number | boolean) => {
      const row = await configRowOf(() => $.config.list(), setting.name)
      if ('refusal' in row) {
        return say(`${setting.label} stays: ${row.refusal}.`, true)
      }
      // Ahead of the write: it reloads the mod, and whatever runs after it may never run.
      const text = `Saved ${setting.label}: ${shown(setting, value)}. It is kept in your settings and the mod reloaded with it.`
      await remember(text, false, true)
      const { deny } = await $.config.set({ key: row.key, value }).catch((error: unknown) => ({ deny: error instanceof Error ? error.message : String(error) }))
      if (deny !== undefined) {
        return say(`${setting.label} stays: ${deny}`, true)
      }
      $.ui.toast(text)
    }

    // One control for any row: a toggle, a pick (a Select, or buttons on mobile) or a text field.
    const control = (row: Row, held: string | boolean, set: (value: string | boolean) => Promise<unknown>, id: string) => {
      if (row.kind === 'toggle') {
        return <Button key={id} label={`${held === true ? '[x]' : '[ ]'} ${row.label}`} plain onPress={() => void set(held !== true)} />
      }
      if (row.kind === 'pick') {
        const choices: readonly Choice[] = row.choices
        if (fields === undefined) {
          return (
            <Box flexWrap="wrap" columnGap={1}>
              <Text>{`${row.label}:`}</Text>
              {choices.map(one => (
                <Button key={`${id}-${one.value}`} label={`${held === one.value ? '▸ ' : ''}${one.label}`} plain dimColor={held !== one.value} onPress={() => void set(one.value)} />
              ))}
            </Box>
          )
        }

        return <fields.Select key={id} label={row.label} value={String(held)} options={choices} onSelect={value => void set(value)} />
      }
      if (fields === undefined) {
        return <Text>{`${row.label}: ${shown(row, held)}. Change it in /config.`}</Text>
      }

      return (
        <Box width={width}>
          <fields.Input key={id} label={`${row.label} `} value={String(held)} placeholder="none" submitLabel="save" onSubmit={text => void set(text)} />
        </Box>
      )
    }
    const line = (row: Row, control_: ReturnType<typeof control>) => (
      <Box flexDirection="column">
        {control_}
        <Text dimColor wrap="truncate-end">{row.help}</Text>
      </Box>
    )

    // A text row's number or URL is checked before it is written; a pick only ever sends one of its choices.
    const defaultRow = (setting: Setting) => {
      const held = heldBy(options, setting)
      const set = async (value: string | boolean) => {
        if (typeof value === 'boolean') {
          return changeDefault(setting, value)
        }
        if (setting.kind === 'pick') {
          return isChoice(setting, value) ? changeDefault(setting, value) : say(`${value} is not one of ${setting.label}'s choices.`, true)
        }
        const parsed = parseText(setting, value)

        return 'refusal' in parsed ? say(parsed.refusal, true) : changeDefault(setting, parsed.value)
      }

      return line(setting, control(setting, held, set, `d-${setting.name}`))
    }
    const taskRow = (row: TaskRow, task: NonNullable<typeof open>) => line(row, control(row, taskValue(task, row.field), value => changeTask(row, value), `t-${row.name}`))

    const hasKey = (typeof options.jevApiKey === 'string' && options.jevApiKey !== '') || ((await $.env.get('TYPESAFE_API_KEY').catch(() => undefined)) ?? '') !== ''

    return (
      <Box flexDirection="column">
        <Box justifyContent="space-between" paddingRight={2}>
          <Text bold>Settings</Text>
          <Button key="board" label="Board" hotkey="b" plain onPress={() => void $.ui.close({ id: SETTINGS }).then(() => $.ui.open(RAIL_OPEN))} />
        </Box>
        {note?.note ? <Text {...(note.isBad ? { color: 'warning' as const } : { dimColor: true })} wrap="wrap">{note.note}</Text> : null}
        {open === null ? null : (
          <Box flexDirection="column" marginTop={1}>
            <Text bold wrap="truncate-end">{`This task: ${fit(open.title, width - 12)}`}</Text>
            {TASK_ROWS.map(row => taskRow(row, open))}
            <Box flexDirection="column" marginTop={1}>
              <Text>{`Worktree: ${open.worktree === 'now' ? 'its own' : 'this checkout'}`}</Text>
              <Text dimColor wrap="truncate-end">Fixed when the task starts: it is entered with the first stage.</Text>
            </Box>
          </Box>
        )}
        <Box flexDirection="column" marginTop={1}>
          <Text bold>Defaults for new tasks and the mod</Text>
          <Text dimColor wrap="truncate-end">A change is saved to your settings and the mod reloads.</Text>
          {DEFAULTS.map(defaultRow)}
          <Box flexDirection="column" marginTop={1}>
            <Text>{`TypeSafe API key: ${hasKey ? 'set' : 'not set'}`}</Text>
            <Text dimColor wrap="truncate-end">Set it in /config, or as TYPESAFE_API_KEY. Never shown here.</Text>
          </Box>
        </Box>
        <Box marginTop={1}>
          <Text dimColor>{isInline ? 'tab ↑↓ move · enter selects · esc closes' : 'tab moves · enter selects · ↑↓ scroll · esc back'}</Text>
        </Box>
      </Box>
    )
  })
}

