// The new-task dialog's draft as pure functions: what typing, picking and
// creating do to it. dialog.tsx draws it and writes it to state.
import type { FlowCreate, FlowDefaults, FlowDraft, FlowEffort, FlowHelpers, FlowWorkflow } from '../types'
import { GATED, inferEntry, isHelpers, slugify, stagesOf } from './flow'
import { EFFORTS, FLOWS, FLOW_NAMES, FLOW_OF, MODELS, stageLabel } from './flows'
import type { BriefVerdict } from './jev'
import { BUILD } from './proof'
import { GATE, PROOF } from './strip'
import type { Segment } from './strip'

export const blankDraft = (defaults: FlowDefaults = {}): FlowDraft => ({
  text: '',
  title: '',
  flow: 'grill',
  isFlowPicked: false,
  finish: 'pr',
  worktree: 'never',
  model: defaults.model ?? '',
  effort: '',
  planModel: defaults.planModel ?? '',
  planEffort: '',
  helpers: defaults.helpers ?? '',
  critic: defaults.critic ?? false,
  rules: defaults.rules ?? '',
  ui: false,
})

/** The name a task gets from its text: the first line, as createTask cuts it. */
export const titleOf = (text: string) => (text.split('\n')[0] ?? '').trim().slice(0, 72)

/** The draft after the text changed: the name and the guessed flow follow it unless the person set them. */
export const typed = (draft: FlowDraft, text: string): FlowDraft => ({
  ...draft,
  text,
  // A name that still equals the old first line was never edited by hand.
  title: draft.title === titleOf(draft.text) ? titleOf(text) : draft.title,
  hint: undefined,
  flow: draft.isFlowPicked ? draft.flow : FLOW_OF[inferEntry(text)],
})

export const picked = (draft: FlowDraft, flow: FlowWorkflow): FlowDraft => ({ ...draft, flow, isFlowPicked: true })

/** The draft with a classifier's guess, unless the person picked a flow in the meantime. */
export const guessed = (draft: FlowDraft, flow: FlowWorkflow): FlowDraft => (draft.isFlowPicked ? draft : { ...draft, flow })

/** The draft with Jev's read of the brief: a guessed flow (never over a pick), the UI suggestion and the hint. */
export const judged = (draft: FlowDraft, verdict: BriefVerdict): FlowDraft => ({
  ...(verdict.flow === undefined ? draft : guessed(draft, verdict.flow)),
  isUiSuggested: verdict.isUi,
  hint: verdict.hint,
})

/** The helpers a Select value names; anything else keeps each helper's own model. */
export const helpersOf = (value: string): FlowHelpers | '' => (isHelpers(value) ? value : '')

/** The helper routes in words, as the dialog offers them. */
export const HELPERS: readonly { value: FlowHelpers; label: string; short: string }[] = [
  { value: 'stage', label: 'Follow the stage', short: 'helpers follow the stage' },
  ...MODELS.map(one => ({ value: one.alias, label: one.label, short: `helpers on ${one.label}` })),
]

const modelLabel = (model: string) => MODELS.find(one => one.alias === model)?.label ?? model
const runsOn = (model: string, effort: string, fallback: string) =>
  [model === '' ? fallback : modelLabel(model), effort === '' ? undefined : `at ${effort}`].filter(Boolean).join(' ')

/** The workflow's line, ending the way the draft's When done does. */
export const blurbOf = (d: Pick<FlowDraft, 'flow' | 'finish'>) =>
  FLOWS[d.flow].blurb.replace(/(, then| and) open the PR$/, (all, joint: string) => (d.finish === 'pr' ? all : d.finish === 'push' ? `${joint} push it to main` : ''))

/** What the folded options are set to, in words. */
export const optionsSummary = (d: FlowDraft) =>
  [
    d.finish === 'pr' ? 'Opens a PR' : d.finish === 'push' ? 'Pushes to main' : 'No PR',
    d.worktree === 'now' ? 'own worktree' : undefined,
    d.ui ? 'proof is seeing it work' : undefined,
    d.critic ? 'build reviewed before it closes' : undefined,
    d.rules.trim() === '' ? undefined : `rules from ${d.rules.trim()}`,
  ]
    .filter(Boolean)
    .join(' · ')

/** What the folded models are set to, in words; `hasPlanning` when the workflow has planning stages. */
export const modelsSummary = (d: FlowDraft, hasPlanning: boolean) =>
  [
    hasPlanning && (d.planModel !== '' || d.planEffort !== '') ? `Plans on ${runsOn(d.planModel, d.planEffort, 'the build model')}` : undefined,
    `${hasPlanning ? 'Builds' : 'Runs'} on ${runsOn(d.model, d.effort, 'the session model')}`,
    HELPERS.find(one => one.value === d.helpers)?.short,
  ]
    .filter(Boolean)
    .join(' · ')

/** The effort a Select value names; anything else keeps the session's. */
export const effortOf = (value: string): FlowEffort | '' => EFFORTS.find(one => one === value) ?? ''

/** The folder the task will live in, from the name it will get. */
export const slugPath = (draft: FlowDraft) => `.scratch/${slugify(draft.title.trim() || titleOf(draft.text))}/`

/** The flow a classifier label names; labels read `<flow>: <blurb>`. */
export const flowLabels = FLOW_NAMES.map(name => `${name}: ${FLOWS[name].blurb}`)
export const flowOfLabel = (label: string | undefined) => FLOW_NAMES.find(name => label?.startsWith(`${name}:`))

/** The stages the drafted workflow will run, all ahead, with the gates a person approves and the build's proof gate marked: what the dialog's strip draws. */
export const preview = (draft: FlowDraft): Segment[] =>
  stagesOf({ flow: draft.flow, entry: inferEntry(draft.text), finish: draft.finish }).map(stage => ({
    stage,
    label: stageLabel(stage),
    state: 'ahead' as const,
    ...(stage in GATED ? { gate: 'ahead' as const } : {}),
    ...(BUILD.includes(stage) ? { proof: 'ahead' as const } : {}),
  }))

/** What the preview's marks mean, for the marks it shows; undefined when it shows none. A task with a UI must also be seen working. */
export const previewLegend = (stages: Segment[], isUi = false) =>
  [
    stages.some(one => one.gate !== undefined) ? `${GATE} You approve it` : undefined,
    stages.some(one => one.proof !== undefined) ? `${PROOF.ahead} Done once its checks pass${isUi ? ' and the change is seen working' : ''}` : undefined,
  ]
    .filter(Boolean)
    .join(' · ') || undefined

/** Why Create does nothing yet, or undefined when it can go ahead. */
export const blocker = (draft: FlowDraft) => (draft.text.trim() === '' ? 'Describe what to build first.' : undefined)

const ISSUE_URL = /^https:\/\/github\.com\/[\w.-]+\/[\w.-]+\/issues\/\d+\/?$/

/** What `gh issue view` takes for text that is only a GitHub issue reference, else undefined. */
export const githubRef = (text: string) => {
  const one = text.trim()

  return /^#\d+$/.test(one) ? one.slice(1) : ISSUE_URL.test(one) ? one : undefined
}

/** The file an `@<path>` reference at the start of the text names, and what follows it; undefined for any other text. */
export const attachment = (text: string) => {
  const found = /^@(\S*\/\S*)(?:\s+([\s\S]*))?$/.exec(text.trim())

  return found?.[1] === undefined ? undefined : { path: found[1], note: (found[2] ?? '').trim() }
}

/** A brief read from a file: its name, from the first heading or line, and the text the task keeps as its ticket. */
export type Brief = { title: string; body: string }

/** The brief a file's contents make, with any words typed after the path put ahead of them; undefined for an empty or binary file. */
export const briefOf = (contents: string, note = ''): Brief | undefined => {
  const body = contents.trim()
  const first = body.split('\n').find(line => line.trim() !== '')
  if (first === undefined || contents.includes('\0')) {
    return undefined
  }

  return { title: titleOf(first.replace(/^#+\s*/, '')), body: note === '' ? body : `${note}\n\n${body}` }
}

/** Whether the name is still the text's first line or empty, so nobody typed it. */
const isAutoTitle = (draft: FlowDraft) => draft.title.trim() === '' || draft.title === titleOf(draft.text)

/** The draft named after its brief file, unless the person named it. */
export const named = (draft: FlowDraft, brief: Brief): FlowDraft => (isAutoTitle(draft) ? { ...draft, title: brief.title } : draft)

export type Issue = { title: string; url: string; body: string }

/** The issue `gh issue view --json title,body,url` printed, or why it could not be read. */
export const issueOf = (ran: { exitCode: number; stdout: string; stderr: string }): Issue | string => {
  if (ran.exitCode !== 0) {
    return ran.stderr.trim().split('\n')[0] || `gh exited ${ran.exitCode}`
  }
  try {
    const { title, url, body } = JSON.parse(ran.stdout) as Partial<Issue>

    return typeof title === 'string' && typeof url === 'string' ? { title, url, body: body ?? '' } : 'gh printed no issue'
  } catch {
    return 'gh printed no issue'
  }
}

/** What the dialog creates; a brief file is kept as the ticket and names the task; an issue makes the task start at `ticket` and carry the issue as its ticket. */
export const createFrom = (draft: FlowDraft, issue?: Issue, brief?: Brief): FlowCreate => {
  const title = isAutoTitle(draft) ? (issue?.title ?? brief?.title ?? draft.title.trim()) : draft.title.trim()

  return {
    text: brief?.body ?? draft.text.trim(),
    ...(brief === undefined ? {} : { ticket: brief.body }),
    ...(title === '' ? {} : { title }),
    ...(issue === undefined ? {} : { start: 'ticket' as const, ticket: `# ${issue.title}\n\n${issue.url}\n\n${issue.body}`.trim() }),
    flow: draft.flow,
    finish: draft.finish,
    worktree: draft.worktree,
    ...(draft.model === '' ? {} : { model: draft.model }),
    ...(draft.effort === '' ? {} : { effort: draft.effort }),
    ...(draft.planModel === '' ? {} : { planModel: draft.planModel }),
    ...(draft.planEffort === '' ? {} : { planEffort: draft.planEffort }),
    ...(draft.helpers === '' ? {} : { helpers: draft.helpers }),
    ...(draft.critic ? { critic: true } : {}),
    ...(draft.rules.trim() === '' ? {} : { rules: draft.rules.trim() }),
    ...(draft.ui ? { ui: true } : {}),
  }
}

