// An issue artifact read through the tracker's own CLI: the command that
// prints it and the Markdown the tab draws from what it printed. Pure.

/** The command that prints an issue as JSON: `gh` for GitHub, `glab` for GitLab. */
export const viewArgv = (url: string) =>
  /\/-\/|gitlab/i.test(url) ? ['glab', 'issue', 'view', url, '--output', 'json'] : ['gh', 'issue', 'view', url, '--json', 'title,body,state']

/** An issue as the tab draws it, from what `viewArgv` printed (`body` on GitHub, `description` on GitLab); undefined when it is not one. */
export const issueText = (stdout: string) => {
  const found: unknown = (() => {
    try {
      return JSON.parse(stdout)
    } catch {
      return undefined
    }
  })()
  if (typeof found !== 'object' || found === null || !('title' in found) || typeof found.title !== 'string') {
    return undefined
  }
  const body = 'body' in found ? found.body : 'description' in found ? found.description : ''
  const state = 'state' in found && typeof found.state === 'string' ? `*${found.state.toLowerCase()}*\n\n` : ''

  return `# ${found.title}\n\n${state}${typeof body === 'string' ? body : ''}`
}

