files.types/index.d.ts:
/** Where a task joins the flow: ask-matt's main flow or one of its on-ramps. */
export type FlowEntry = 'ticket' | 'idea' | 'broken' | 'foggy'

/**
 * How a task proceeds, picked when it is created: a fixed chain of stages
 * (oneshot, grill, spec), or none (freeform).
 */
export type FlowWorkflow = 'oneshot' | 'grill' | 'spec' | 'wayfind' | 'architecture' | 'freeform'

export type FlowEffort = 'low' | 'medium' | 'high' | 'xhigh' | 'max'

/** A model a task can pick by name; the engine resolves it to the family's latest. */
export type FlowModelAlias = 'fable' | 'opus' | 'sonnet' | 'haiku'

/**
 * What the built-in helper agents run on: `stage` the model the task's current stage runs on
 * (the plan model while planning), or one model throughout. Absent, each keeps its own.
 */
export type FlowHelpers = 'stage' | FlowModelAlias

/**
 * Where the task stands for a person: a turn runs, a stage is under way between turns,
 * a gate waits for approval, a build's code edits have no passing check yet, a loop needs a
 * person to break it, the next stage is ready, or the task is closed.
 */
export type FlowStatus = 'working' | 'progress' | 'waiting' | 'proof' | 'stuck' | 'ready' | 'done'

/** One skill that ran while the task was open. */
export type FlowStep = { skill: string; at: number }

/** What a phase produced: a repo-relative path under `.scratch/`, or an issue or PR URL. */
export type FlowArtifact = { phase: string; pointer: string; at: number }

/** An issue artifact as the doc tab draws it: the fetched text, or the reason there is none. */
export type FlowIssue = { pointer: string; text?: string; error?: string }

/**
 * One thing that happened to the task, for gates, evidence and the retro:
 * a person approved a phase or lifted its edit gate, the gate held an edit,
 * a check ran, a PR's CI settled, the task grew into a bigger flow, the
 * model reported a stage finished or blocked, a build stage's code was
 * edited (kept once per run of edits, so a later check can prove them), the
 * person's prompt read as a complaint about earlier work, the turn's
 * evidence was judged against what the task needs, or the change was seen
 * working (the repo's verify skill ran, or a proof file was saved), or a second look at a build
 * named what it likely missed, or the build's edits were undone (a clean tree and no
 * commit since the first edit), which leaves nothing to prove, or Jev judged a block
 * unnecessary and waived it, or a stage reported a fork it settled (what, why, evidence).
 */
export type FlowEvent = {
  kind: 'approve' | 'allow' | 'held' | 'check' | 'ci' | 'flow' | 'done' | 'edit' | 'blocked' | 'rework' | 'judged' | 'seen' | 'critic' | 'reverted' | 'waived' | 'decision'
  phase: string
  at: number
  /** The held or edited path, the check's command, the PR URL, the flow the task grew into, what blocks the stage, why Jev waived a block, a decision, or the reason a person gave for an allow or a skip. */
  detail?: string
  /** For a check or CI: whether it passed. For a judged turn: whether its evidence was enough. */
  ok?: boolean
  /** For a waiver: the block Jev lifted, a gate's approval, one code edit in planning, or a build's proof where no check exists. */
  block?: FlowBlock
}

/** A block Jev can waive when it judges a person or a check is not needed there. */
export type FlowBlock = 'gate' | 'edit' | 'proof'

/** What Jev made of a block: lifted or kept, and why, in a few words. */
export type FlowWaiver = { block: FlowBlock; isWaived: boolean; detail: string }

/**
 * A block to ask Jev about: the current gate's document, one code edit a planning phase would
 * hold (its repo-relative path and the text it writes), or a build's missing check, with the
 * stage's report standing in for the turn's last message.
 */
export type FlowWaive = { block: 'gate' } | { block: 'edit'; path: string; text: string } | { block: 'proof'; summary: string }

/** How a task ends after its build: a pull request, a push to the default branch, or neither. */
export type FlowFinish = 'pr' | 'push' | 'none'

export type FlowTask = {
  slug: string
  title: string
  entry: FlowEntry
  flow: FlowWorkflow
  /** How the flow ends: the `pr` stage, the `push` stage, or no such stage. */
  finish: FlowFinish
  /** `now`: the task works in its own git worktree. */
  worktree: 'now' | 'never'
  /** The model the task's turns run on; absent keeps the session's. */
  model?: string
  /** The effort the task's turns run at; absent keeps the session's. */
  effort?: FlowEffort
  /** The model and effort the planning stages run on instead; each absent falls back to `model` and `effort`. */
  planModel?: string
  planEffort?: FlowEffort
  /** What the built-in helper agents run on while the task is open; absent keeps theirs. */
  helpers?: FlowHelpers
  /** A build stage gets a second look (a fork of the session) before it is recorded finished. */
  critic?: boolean
  /** A file of house rules (repo-relative or absolute) appended to every stage skill as it loads. */
  rules?: string
  /** The task changes something a person sees: its build is proven only once the change was seen working. */
  ui?: boolean
  /** Where the repo tracks work, when it is an issue tracker: the gate prefers an issue to a file of the same document. */
  tracker?: 'github' | 'gitlab'
  /** The last stage skill that ran, or `new` before the first. */
  phase: string
  history: FlowStep[]
  /** Oldest first; a later artifact wins over an earlier one. */
  artifacts: FlowArtifact[]
  /** Oldest first. */
  log: FlowEvent[]
  createdAt: number
  closedAt?: number
}

/**
 * The one recommended next command, without its slash, the stage it runs when it runs one,
 * and the step a person may take instead.
 */
export type FlowNext = {
  command: string
  args?: string
  stage?: string
  why: string
  alt?: { command: string; args?: string; label: string }
}

/** A yes-or-no judgment: Jev answers the probability of yes. */
export type JevNoul = { type: 'noul'; instructions: string; criteria?: { true: string; false: string } }
/** One of a defined set; a null description leaves the option's name to speak for itself. */
export type JevChoice<Option extends string = string> = { type: 'choice'; instructions: string; criteria: Record<Option, string | null> }
/** A position on ordered levels, lowest first. */
export type JevScore = { type: 'score'; instructions: string; criteria: readonly string[] }
export type JevQuestion = JevNoul | JevChoice | JevScore
export type JevAnswer<Question> = Question extends JevNoul
  ? { noul: number }
  : Question extends JevChoice<infer Option>
    ? { choice: Option; confidence: number }
    : Question extends JevScore
      ? { score: number; confidence: number }
      : never
export type JevAnswers<Questions> = { [Id in keyof Questions]: JevAnswer<Questions[Id]> }
/** `off` never calls Jev; `shadow` calls and logs; `on` also acts on the answers. */
export type JevMode = 'off' | 'shadow' | 'on'

/** What a new task is made from: `/flow new` or the new-task dialog. */
export type FlowCreate = {
  text: string
  /** The task's name; the first line of `text` when absent. */
  title?: string
  start?: FlowEntry
  flow?: FlowWorkflow
  finish?: FlowFinish
  worktree?: 'now' | 'never'
  model?: string
  effort?: FlowEffort
  planModel?: string
  planEffort?: FlowEffort
  helpers?: FlowHelpers
  critic?: boolean
  rules?: string
  /** The task changes something a person sees. */
  ui?: boolean
  /**
   * The ticket to keep at `.scratch/<slug>/ticket.md`, which the first stage reads.
   * Multi-line `text` is kept the same way when this is absent.
   */
  ticket?: string
}

/** What a new task starts with unless the person sets it: the plugin's options. */
export type FlowDefaults = Pick<FlowCreate, 'model' | 'planModel' | 'helpers' | 'critic' | 'rules'>

/** The new-task dialog's fields while it is open. */
export type FlowDraft = {
  text: string
  title: string
  flow: FlowWorkflow
  /** Whether the person picked the flow, so a later guess never overrides it. */
  isFlowPicked: boolean
  finish: FlowFinish
  worktree: 'now' | 'never'
  /** Empty keeps the session's. */
  model: string
  effort: FlowEffort | ''
  /** For the planning stages; empty falls back to `model` and `effort`. */
  planModel: string
  planEffort: FlowEffort | ''
  /** Empty keeps each helper agent's own model. */
  helpers: FlowHelpers | ''
  /** Whether a build stage gets a second look before it is recorded finished. */
  critic: boolean
  /** The house rules file; empty for none. */
  rules: string
  /** Whether the task changes something a person sees, so its proof is the change seen working. */
  ui: boolean
  /** Jev's one line on what the brief leaves out, shown under the text; the text changing clears it. */
  hint?: string
  /** Jev read the brief as changing something a person sees: the Has a UI toggle is suggested, never forced. */
  isUiSuggested?: boolean
  /** Which folded section of the dialog is open: the options (PR, worktree, UI) or the models; none folds both into a line each. */
  openSection?: 'options' | 'models'
}

/** A task as the board artifact reads it: one document in its `tasks` collection. */
export type FlowBoardTask = {
  repo: string
  slug: string
  title: string
  entry: FlowEntry
  flow: FlowWorkflow
  /** Where the task stands; the board never knows a turn runs, so never `working`. */
  status: FlowStatus
  /** How the flow ends. */
  finish: FlowFinish
  /** The model and effort the task's turns run at, when set. */
  model?: string
  effort?: FlowEffort
  phase: string
  isOpen: boolean
  next: FlowNext
  rail: {
    stage: string
    state: 'done' | 'now' | 'ahead'
    /** For the spec and tickets stages: whether a person approved them, or Jev waived the wait. */
    gate?: 'approved' | 'waived' | 'waiting' | 'ahead'
    /** For a build stage whose code was edited: whether every check since the last edit passes. */
    proof?: 'proven' | 'needed'
    /** The stage in words (`Write the spec`); older documents lack it. */
    label?: string
    /** The command that runs the stage, when it differs from the stage (`wayfinder` for `wayfinder-clear`). */
    command?: string
    artifacts: string[]
  }[]
  evidence: string[]
  /** Why the task needs proof or a person, while it does; older documents lack it, as they do the next two. */
  hold?: string
  /** The build's counts in words: its round, a failing check's tries, the reworks. */
  tally?: string[]
  /** What showed the change working since the last code edit: `verify`, or a proof file's path. */
  seen?: string
  ci?: { ok: boolean; url: string }
  journey: { at: number; kind: string; what: string; ok?: boolean }[]
  createdAt: number
  updatedAt: number
  closedAt?: number
}

/** A catch-up run on the side: the task it is for, the subagent, and what it answered. */
export type FlowRecap = { slug: string; agentId?: string; brief?: string; error?: string; at: number }

export type Flow = {
  /** The open task for this project, or null. */
  task: () => Promise<FlowTask | null>
  /** Opens a new task, or resumes the one with the same slug, and makes it the open one. */
  create: (input: FlowCreate) => Promise<{ task: FlowTask; isNew: boolean }>
  /** Every task under `.scratch/`, open or closed, newest first. */
  all: () => Promise<FlowTask[]>
  /** The recommended next command for the open task, or null. */
  next: () => Promise<FlowNext | null>
  /** Offers the open task's next step as ghost text in the empty prompt, when it has one to offer now. */
  suggest: () => Promise<void>
  /** Opens the board pane with the keyboard: docked beside the transcript, or inline as a dialog Esc closes. */
  show: (input: { docks: boolean }) => Promise<void>
  /**
   * Runs the recommended next command (or, with `alt`, the step a person may
   * take instead), in the task's worktree when it has one; with `expect`, only
   * while that task is still open in that phase. Toasts why it cannot.
   */
  run: (input?: { alt?: boolean; expect?: { slug: string; phase: string } }) => Promise<void>
  /** Records that a skill ran; stage skills move the task's phase. */
  enter: (input: { skill: string }) => Promise<FlowTask | null>
  /** Records an artifact for the current phase. */
  produce: (input: { pointer: string }) => Promise<FlowTask | null>
  /** Points the artifact tab at an artifact; for an issue, fetches its text with gh or glab first. */
  doc: (input: { pointer: string }) => Promise<void>
  /** Starts a catch-up for the open task in a background subagent, unless one is running. */
  recap: () => Promise<{ isStarted: boolean; reason?: string }>
  /** Closes the open task and, when nothing would be lost, returns the repo to its default branch, pulled, the merged branch deleted. Says what it did. */
  close: () => Promise<string>
  /** Skips the stage under way, or the next one once the current is done, recorded as skipped with the person's reason if given; null when nothing is left. */
  skip: (input?: { reason?: string }) => Promise<FlowTask | null>
  /** Closes the open task and opens its retro's findings as a Oneshot task; null when there are none. */
  followUp: () => Promise<FlowTask | null>
  /** Records where the repo tracks work (an issue tracker), which the gates read. */
  track: (input: { tracker: 'github' | 'gitlab' }) => Promise<FlowTask | null>
  /** Records something that happened in the current phase. */
  note: (input: Omit<FlowEvent, 'phase' | 'at'>) => Promise<FlowTask | null>
  /** Records that a build stage's code at `path` was edited, unless an unproven edit is already on record. */
  edited: (input: { path: string }) => Promise<FlowTask | null>
  /** Approves the current gated phase's artifact. */
  approve: () => Promise<FlowTask | null>
  /** Lifts the code-edit gate for the rest of the current planning phase, or waives the proof a build stage's edits still need. */
  allow: (input?: { reason?: string }) => Promise<FlowTask | null>
  /** Polls a PR's checks until they settle, then notes the outcome. */
  watch: (input: { url: string }) => Promise<void>
  /** Sets the board artifact every task is sent to (a claude.ai artifact URL), or clears it with null. */
  share: (input: { url: string | null }) => Promise<void>
  /** The board artifact's URL, or null when none is set. */
  board: () => Promise<string | null>
  /** Sends these tasks (default: the open one) to the board now; resolves to how many went. */
  sync: (input?: { tasks?: FlowTask[] }) => Promise<number>
  /** Reads `.scratch/<slug>/task.json`, or null when there is none. */
  load: (input: { slug: string }) => Promise<FlowTask | null>
  /** Writes the task and makes it this project's open task, or clears it once closed. */
  save: (task: FlowTask) => Promise<void>
  /**
   * Asks Jev the questions about `state` and resolves the typed answers, or null when Jev is off,
   * has no key, answered late or answered something unreadable: every caller fails open on null.
   */
  judge: <Questions extends Record<string, JevQuestion>>(input: {
    state: unknown
    questions: Questions
    timeoutMs?: number
  }) => Promise<JevAnswers<Questions> | null>
  /**
   * Asks Jev whether a block is needed, logs the answer, and in `on` records a waiver Jev is sure
   * of on the task. Resolves that waiver, or null when the block stays: off, shadow, no key, no
   * answer or a doubtful one all keep it.
   */
  waive: (input: FlowWaive) => Promise<FlowWaiver | null>
  /** Reopens this project's open task from disk at session start. */
  resume: () => Promise<FlowTask | null>
}

declare module 'claude-code' {
  interface EngineInterface {
    flow: Flow
  }
  interface PluginState {
    flow: {
      task: FlowTask | null
      /** Whether a model turn is running now. */
      busy: boolean
      /** The new-task dialog's fields while it is open. */
      draft: FlowDraft | null
      /** The artifact pointer the doc tab shows; null shows the latest. */
      doc: string | null
      /** What the doc tab shows for an issue artifact: its text as fetched, or why it could not be. */
      issue: FlowIssue | null
      /** Whether the next stage runs once the current turn answers (autoAdvance after stage_done). */
      advance: boolean
      /** The settings pane: its last confirmation or refusal, and whether the next load (an option change reloads the mod) opens it again. */
      settings: { reopen: boolean; note: string; isBad: boolean }
      /** The latest catch-up, run on the side by a subagent: running while it has neither a brief nor an error. */
      recap: FlowRecap | null
      /** The board's own view: its details section open, and a close waiting for its second press. */
      /** `closing`: the slug of the task Close was pressed once on, so a second press closes only that one. */
      boardView: { isWhyOpen: boolean; closing?: string }
    }
  }
}
